  async function loadDashboard(){try{const d=await callHost('getWorkbenchSummary');const cards=[['Resources',d.resourceCount],['Unsorted',d.unsortedCount],['Not analysed',d.notAnalysedCount],['Images',d.imageCount],['Coursework',d.courseworkCount],['Knowledge links',d.knowledgeLinkCount]];$('dashboardCards').innerHTML=cards.map(([l,v])=>`<div class="metric-card"><strong>${Number(v||0).toLocaleString()}</strong><span>${esc(l)}</span></div>`).join('');const opportunities=[['Source analyses',d.sourceAnalysisRunCount,'Selected scans staged as source material'],['Raw fragments',d.rawFragmentCount,'Not lessons — awaiting reconstruction/review'],['Prototype lessons',d.prototypeLessonCount,'Preserved v0.5 material needing recomposition'],['Evidence candidates',d.evidenceCandidateCount,'Coursework/resources that may support reviewed career evidence'],['Career paths',d.careerPathCount,'Real career routes, separate from knowledge organisation']];$('workbenchOpportunityGrid').innerHTML=opportunities.map(([label,value,note])=>`<article class="opportunity-card"><span>${esc(label)}</span><strong>${Number(value||0).toLocaleString()}</strong><small>${esc(note)}</small></article>`).join('');}catch(e){toast(e.message,true);}}

