  async function loadSourceAnalysisWorkbench(){try{const s=await callHost('getSourceAnalysisWorkbenchSummary');const cards=[['Analysis runs',s.runCount],['Completed',s.completedRuns],['Raw fragments',s.rawFragmentCount],['Derived assets',s.assetCount],['Needs review',s.needsReviewCount],['Failed runs',s.failedRunCount]];$('sourceAnalysisStats').innerHTML=cards.map(([l,v])=>`<div class="metric-card"><strong>${Number(v||0).toLocaleString()}</strong><span>${esc(l)}</span></div>`).join('');$('sourceAnalysisMessage').innerHTML=`<strong>Staging is active</strong><p>${Number(s.runCount||0).toLocaleString()} deliberate scan${Number(s.runCount||0)===1?' has':'s have'} a source-analysis record. v0.5 scanned text was migrated as legacy raw extraction so it can be recomposed later rather than lost.</p>`;}catch(e){toast(e.message,true);}}

