  async function loadProjectWorkbench(){
    try{const items=await callHost('getCareerProjects');if($('projectStats'))$('projectStats').innerHTML=[['Projects',items.length],['Private / no-web',items.filter(x=>x.noWebAccess).length],['CV eligible',items.filter(x=>x.cvEligible).length],['Portfolio eligible',items.filter(x=>x.portfolioEligible).length]].map(([l,v])=>`<div class="metric-card"><strong>${Number(v||0).toLocaleString()}</strong><span>${esc(l)}</span></div>`).join('');const list=$('careerProjectList');if(list)list.innerHTML=items.length?items.map(x=>`<button class="career-record-card project-record" data-project-id="${x.id}"><span class="eyebrow">${esc(x.category)} · ${esc(x.status)}</span><strong>${esc(x.name)}</strong><span>${esc(x.summary||'No summary yet.')}</span><small>${x.noWebAccess?'No web access · ':''}${Number(x.resourceCount||0)} resources · ${Number(x.journalCount||0)} journal entries</small></button>`).join(''):'<div class="empty">No project workspaces yet.</div>';document.querySelectorAll('.project-record').forEach(b=>b.addEventListener('click',()=>openCareerProject(Number(b.dataset.projectId))));}catch(e){toast(e.message,true);}
  }
  async function openCareerProject(id){try{const d=await callHost('getCareerProject',{projectId:id});if(!d)return;const p=$('careerProjectDetail');p.hidden=false;p.innerHTML=`<p class="eyebrow">${esc(d.project.category)} · ${esc(d.project.privacyMode)}</p><h3>${esc(d.project.name)}</h3><p>${esc(d.project.summary||'')}</p><div class="evidence-rule-grid"><div><strong>${Number(d.project.resourceCount||0)}</strong><span>Linked resources</span></div><div><strong>${Number(d.project.journalCount||0)}</strong><span>Journal entries</span></div><div><strong>${d.project.noWebAccess?'Yes':'No'}</strong><span>No web access</span></div><div><strong>${d.project.portfolioEligible?'Eligible':'Private'}</strong><span>Portfolio state</span></div></div><div class="stack-form"><input id="journalTitle" placeholder="Journal entry title"><textarea id="journalBody" placeholder="Observation, failure, test, decision or lesson learned"></textarea><button id="addProjectJournal" class="secondary-btn">Add private journal entry</button></div>`;$('addProjectJournal').addEventListener('click',async()=>{try{await callHost('addProjectJournalEntry',{projectId:id,entryType:'Note',title:$('journalTitle').value,body:$('journalBody').value,isPrivate:true});toast('Private project journal entry saved.');await loadProjectWorkbench();await openCareerProject(id);}catch(e){toast(e.message,true);}});p.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast(e.message,true);}}
  async function createCareerProject(){const name=$('projectName')?.value.trim();if(!name){toast('Project name is required.',true);return;}try{await callHost('createCareerProject',{name,category:$('projectCategory').value,summary:$('projectSummary').value,privacyMode:$('projectPrivacy').value,noWebAccess:$('projectNoWeb').checked});$('projectName').value='';$('projectSummary').value='';toast('Project workspace created.');await loadProjectWorkbench();}catch(e){toast(e.message,true);}}

  async function loadSources(){
    try{
      const sources=await callHost('getSources');
      const active=sources.filter(s=>s.lifecycleStatus!=='Removed');
      const removed=sources.filter(s=>s.lifecycleStatus==='Removed');
      const card=s=>{const disabled=s.lifecycleStatus==='Disabled';return `<article class="source-card ${disabled?'source-disabled':''}"><div><h3>${esc(s.name)}</h3><div class="source-meta"><span class="tag">${esc(s.subject||'Unassigned')}</span>${s.courseLevel?`<span class="tag">${esc(s.courseLevel)}</span>`:''}<span class="tag">${esc(s.lifecycleStatus||'Active')}</span><span class="tag">Last discovery: ${esc(fmtDate(s.lastDiscoveredUtc))}</span></div><div class="path">${esc(s.rootPath)}</div>${s.exclusions?.length?`<div class="path">Extra exclusions: ${esc(s.exclusions.join(', '))}</div>`:''}</div><div class="source-actions"><button class="secondary-btn verify-source" data-id="${s.id}">Verify source</button><button class="secondary-btn latest-scan-audit" data-id="${s.id}">Latest rescan report</button>${disabled?`<button class="secondary-btn enable-source" data-id="${s.id}">Enable</button>`:`<button class="primary-btn discover" data-id="${s.id}">Rescan source</button><button class="secondary-btn clean-index" data-id="${s.id}">Re-run discovery rules</button><button class="secondary-btn review-exclusions" data-id="${s.id}">Review & cleanup</button><button class="secondary-btn disable-source" data-id="${s.id}">Disable</button>`}<button class="secondary-btn reconnect-source" data-id="${s.id}">Reconnect / change path</button><button class="danger-btn remove-source" data-id="${s.id}">Remove from CareerBuilder</button></div></article>`;};
      $('sourceList').innerHTML=(active.length?active.map(card).join(''):'<div class="empty">No active library sources yet.</div>')+(removed.length?`<div class="section-heading"><h3>Recently Removed</h3><p>Restorable catalogue entries. Original drive files were never deleted.</p></div>${removed.map(s=>`<article class="source-card removed-source"><div><h3>${esc(s.name)}</h3><div class="source-meta"><span class="tag">Removed</span>${s.removedUtc?`<span class="tag">${esc(fmtDate(s.removedUtc))}</span>`:''}</div><div class="path">${esc(s.rootPath)}</div></div><div class="source-actions"><button class="secondary-btn restore-source" data-id="${s.id}">Restore</button><button class="danger-btn purge-source" data-id="${s.id}">Permanently purge catalogue</button></div></article>`).join('')}`:'');
      document.querySelectorAll('.verify-source').forEach(b=>b.addEventListener('click',()=>verifySource(Number(b.dataset.id),b)));
      document.querySelectorAll('.latest-scan-audit').forEach(b=>b.addEventListener('click',()=>showLatestScanAudit(Number(b.dataset.id),true)));
      document.querySelectorAll('.discover').forEach(b=>b.addEventListener('click',()=>discover(Number(b.dataset.id),b)));
      document.querySelectorAll('.clean-index').forEach(b=>b.addEventListener('click',()=>cleanIndex(Number(b.dataset.id),b)));
      document.querySelectorAll('.review-exclusions').forEach(b=>b.addEventListener('click',()=>reviewDiscovery(Number(b.dataset.id),'Pending',true)));
      document.querySelectorAll('.disable-source').forEach(b=>b.addEventListener('click',()=>setSourceEnabled(Number(b.dataset.id),false)));
      document.querySelectorAll('.enable-source').forEach(b=>b.addEventListener('click',()=>setSourceEnabled(Number(b.dataset.id),true)));
      document.querySelectorAll('.reconnect-source').forEach(b=>b.addEventListener('click',()=>reconnectLibrary(Number(b.dataset.id))));
      document.querySelectorAll('.remove-source').forEach(b=>b.addEventListener('click',()=>removeLibrary(Number(b.dataset.id))));
      document.querySelectorAll('.restore-source').forEach(b=>b.addEventListener('click',()=>restoreLibrary(Number(b.dataset.id))));
      document.querySelectorAll('.purge-source').forEach(b=>b.addEventListener('click',()=>purgeLibrary(Number(b.dataset.id))));
    }catch(e){toast(e.message,true);}
  }
  function integrityMetric(label,value){return `<div><span>${esc(label)}</span><strong>${typeof value==='number'?Number(value).toLocaleString():esc(value)}</strong></div>`;}
  function renderSourceIntegrity(r){
    const panel=$('sourceIntegrityPanel');if(!panel)return;panel.hidden=false;
    const sourceState=!r.sourcePathExists?'Unavailable':r.sourcePathReadable?'Readable':'Not readable';
    const warnings=(r.warnings||[]).length?`<div class="integrity-warnings"><strong>Needs attention</strong><ul>${r.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:`<div class="integrity-ok"><strong>No integrity warnings detected.</strong><p>This is a read-only verification result; it does not prove content classification is correct.</p></div>`;
    panel.innerHTML=`<div class="integrity-head"><div><p class="eyebrow">Source + database verification</p><h3>${esc(r.sourceName)}</h3><p class="path">${esc(r.rootPath)}</p></div><span class="tag">${esc(sourceState)}</span></div><div class="integrity-grid">${[
      ['Tracked rows',r.catalogueRows],['Learning catalogue',r.learningCatalogueRows],['Learning included',r.includedResources],['Learning needs review',r.reviewResources],['Project artifacts',r.projectArtifactResources],['Dual-lane resources',r.dualLaneResources],['Policy-excluded rows',r.policyExcludedResourceRows],['Exclusion records',r.exclusionRecords],['Noise-only exclusions',r.noiseOnlyExclusionRecords],['Missing',r.missingResources],['Manual includes',r.manualIncludeOverrides],['Manual excludes',r.manualExcludeOverrides],['Learning Collections',r.learningCollectionCandidates],['Collection-managed items',r.learningCollectionManagedItems],['Collection catalogue paths',r.learningCollectionCataloguePaths],['Collection exclusion paths',r.learningCollectionExclusionPaths],['Fingerprint eligible',r.fingerprintEligible],['Fingerprint pending',r.fingerprintPending],['Structured analysis eligible',r.structuredAnalysisEligible],['Structured analysis pending',r.structuredAnalysisPending],['Orphan organisation rows',r.orphanOrganisationRows],['Orphan subject links',r.orphanSubjectLinks],['Orphan knowledge links',r.orphanKnowledgeLinks],['Interrupted scan rows',r.interruptedScanRuns]
    ].map(([l,v])=>integrityMetric(l,v)).join('')}</div><div class="integrity-foot"><span>SQLite integrity: <strong>${r.databaseIntegrityOk?'OK':'Problem'}</strong></span><span>Foreign-key problems: <strong>${Number(r.foreignKeyProblemCount||0).toLocaleString()}</strong></span><span>Last discovery: <strong>${esc(fmtDate(r.lastDiscoveredUtc))}</strong></span></div>${warnings}`;
    panel.scrollIntoView({behavior:'smooth',block:'start'});
  }
  async function verifySource(id,button){const old=button?.textContent;if(button){button.disabled=true;button.textContent='Verifying…';}try{const r=await callHost('verifyLibrarySource',{sourceId:id});renderSourceIntegrity(r);toast(r.warnings?.length?`Verification complete: ${r.warnings.length} item${r.warnings.length===1?'':'s'} need attention.`:'Source and database verification passed.');}catch(e){toast(e.message,true);}finally{if(button){button.disabled=false;button.textContent=old;}}}
  async function verifyWholeDatabase(){const b=$('verifyDatabase'),old=b.textContent;b.disabled=true;b.textContent='Verifying…';try{const r=await callHost('verifyDatabase');const panel=$('sourceIntegrityPanel');panel.hidden=false;const warnings=(r.warnings||[]).length?`<div class="integrity-warnings"><strong>Needs attention</strong><ul>${r.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:`<div class="integrity-ok"><strong>Database integrity checks passed.</strong></div>`;panel.innerHTML=`<div class="integrity-head"><div><p class="eyebrow">Whole database verification</p><h3>WICareerBuilder catalogue</h3><p class="muted">Read-only SQLite and relationship checks.</p></div><span class="tag">${r.integrityOk?'OK':'Problem'}</span></div><div class="integrity-grid">${[['Active sources',r.activeSources],['Removed sources',r.removedSources],['Tracked rows',r.catalogueRows],['Learning catalogue',r.learningCatalogueRows],['Learning included',r.includedResources],['Learning needs review',r.reviewResources],['Project artifacts',r.projectArtifactResources],['Dual-lane resources',r.dualLaneResources],['Policy-excluded rows',r.policyExcludedResourceRows],['Exclusion records',r.exclusionRecords],['Noise-only exclusions',r.noiseOnlyExclusionRecords],['Missing',r.missingResources],['Learning Collections',r.learningCollectionCandidates],['Orphan organisation rows',r.orphanOrganisationRows],['Orphan subject links',r.orphanSubjectLinks],['Orphan knowledge links',r.orphanKnowledgeLinks],['Interrupted scan rows',r.interruptedScanRuns],['Foreign-key problems',r.foreignKeyProblemCount]].map(([l,v])=>integrityMetric(l,v)).join('')}</div><div class="integrity-foot"><span>SQLite integrity_check: <strong>${esc(r.integrityMessage)}</strong></span></div>${warnings}`;panel.scrollIntoView({behavior:'smooth',block:'start'});toast(r.warnings?.length?'Database verification completed with warnings.':'Database verification passed.');}catch(e){toast(e.message,true);}finally{b.disabled=false;b.textContent=old;}}

  function reviewOperationKey(sourceId){return `wicb.discovery.lastOperation.${sourceId}`;}
  function renderReviewOperation(data){const panel=$('reviewOperationSummary');if(!data){panel.hidden=true;return;}panel.hidden=false;$('reviewOperationTitle').textContent=data.title||'Discovery operation';$('reviewOperationTime').textContent=data.completedUtc?new Date(data.completedUtc).toLocaleString():'';const stats=[];const add=(label,value)=>{if(value!==undefined&&value!==null)stats.push(`<div><span>${esc(label)}</span><strong>${Number(value).toLocaleString()}</strong></div>`);};add('Examined',data.examined);add('Found',data.resourcesFound);add('Included',data.included);add('Review',data.review);add('Excluded',data.excluded??data.policyExcludedFiles);add('Restored',data.restored??data.restoredByRefinedContext);add('Learning catalogue',data.learningCatalogueResources);add('Project artifacts',data.projectArtifactResources);add('Dual-lane',data.dualLaneResources);add('Low-value project noise skipped',data.lowValueProjectNoiseSkipped);add('Context role suggestions',data.contextRoleSuggestions);add('Needs review now',data.pendingCount);add('Auto excluded',data.autoExcludedCount);add('Learning Collections',data.collectionCount);add('Items managed by collections',data.collectionManagedItemCount);$('reviewOperationStats').innerHTML=stats.join('');}
  function saveReviewOperation(sourceId,data){const saved={...data,sourceId,completedUtc:new Date().toISOString()};try{localStorage.setItem(reviewOperationKey(sourceId),JSON.stringify(saved));}catch{}if(activeReviewSourceId===sourceId)renderReviewOperation(saved);}
  function restoreReviewOperation(sourceId){try{const raw=localStorage.getItem(reviewOperationKey(sourceId));renderReviewOperation(raw?JSON.parse(raw):null);}catch{renderReviewOperation(null);}}
  function renderReviewStats(summary){const items=[['Needs review',summary?.pendingCount??0],['Archives',summary?.archiveReviewCount??0],['Learning Collections',summary?.collectionCount??0],['Collection-managed items',summary?.collectionManagedItemCount??0],['Auto excluded',summary?.autoExcludedCount??0],['Manually excluded',summary?.keptExcludedCount??0],['Manually included',summary?.includedCount??0]];$('reviewStats').innerHTML=items.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${Number(value).toLocaleString()}</strong></div>`).join('');}
  function reviewStateTotal(summary,state){return ({Pending:summary?.pendingCount,Archives:summary?.archiveReviewCount,Collections:summary?.collectionCount,AutoExcluded:summary?.autoExcludedCount,KeptExcluded:summary?.keptExcludedCount,Included:summary?.includedCount,All:summary?.allReviewCount})[state]??0;}

  function renderScanAuditChanges(items){
    const list=$('scanAuditChangeList');if(!list)return;
    list.innerHTML=items.length?items.map(x=>`<article class="scan-change-card"><div><strong>${esc(x.fileName)}</strong><div class="path">${esc(x.relativePath)}</div></div><div class="source-meta"><span class="tag">${esc(x.changeType)}</span>${x.discoveryDecision?`<span class="tag">${esc(x.discoveryDecision)}</span>`:''}${x.catalogueLane&&x.catalogueLane!=='None'?`<span class="tag">Lane: ${esc(x.catalogueLane)}</span>`:''}</div>${x.discoveryReason?`<p class="muted">${esc(x.discoveryReason)}</p>`:''}${x.laneReason&&x.catalogueLane&&x.catalogueLane!=='None'?`<p class="mini-note">${esc(x.laneReason)}</p>`:''}</article>`).join(''):'<div class="empty compact-empty">No changes of this type were recorded for the latest rescan.</div>';
  }
  async function loadLatestScanChanges(){
    if(!activeScanAuditSourceId)return;
    try{const type=$('scanAuditChangeType')?.value||'';const items=await callHost('getLatestDiscoveryScanChanges',{sourceId:activeScanAuditSourceId,changeType:type,limit:500});renderScanAuditChanges(items);$('scanAuditChangeCount').textContent=`Showing ${items.length.toLocaleString()} recorded change${items.length===1?'':'s'}${items.length>=500?' (500-item view limit)':''}.`;}catch(e){toast(e.message,true);}
  }
  function renderScanAudit(r){
    const panel=$('scanAuditPanel');if(!panel)return;panel.hidden=false;activeScanAuditSourceId=Number(r.librarySourceId);
    const notes=(r.notes||[]).length?`<div class="integrity-ok"><strong>Rescan notes</strong><ul>${r.notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'';
    const branches=(r.prunedBranches||[]).length?`<div class="pruned-branch-panel"><strong>Context-pruned branches</strong><p class="muted">These branches were stopped before CareerBuilder enumerated their files. Explicit Learning Collections and saved manual includes are protected traversal exceptions.</p>${r.prunedBranches.map(x=>`<article class="scan-change-card"><div><strong>${esc(x.relativePath)}</strong><div class="path">${esc(x.reason)}</div></div><div class="source-meta"><span class="tag">${Number(x.existingCatalogueRows||0).toLocaleString()} catalogue row${Number(x.existingCatalogueRows||0)===1?'':'s'}</span><span class="tag">${Number(x.safelyRemovedRows||0).toLocaleString()} safely removed</span><span class="tag">${Number(x.protectedRows||0).toLocaleString()} retained</span></div></article>`).join('')}</div>`:'';
    panel.innerHTML=`<div class="integrity-head"><div><p class="eyebrow">Persistent rescan report</p><h3>${esc(r.sourceName)}</h3><p class="muted">Started ${esc(fmtDate(r.startedUtc))}${r.completedUtc?` · completed ${esc(fmtDate(r.completedUtc))}`:''}</p></div><span class="tag">${esc(r.status)}</span></div><div class="integrity-grid">${[
      ['Files inspected',r.filesInspected],['Tracked candidates seen',r.cataloguableFilesSeen],['File-level exclusions seen',r.policyExcludedFilesEncountered],['File-level noise skipped',r.hardNoiseSkipped],['Low-value project noise skipped',r.lowValueProjectNoiseSkipped],['Persistent exclusions encountered',r.persistentExclusions],['Unsupported skipped',r.unsupportedFilesSkipped],['Infrastructure dirs skipped',r.infrastructureDirectoriesSkipped],['Context dirs pruned',r.contextDirectoriesSkipped],['Pruned branches',r.prunedBranchCount],['Tracked rows under pruned branches',r.prunedCatalogueRows],['Scanner leakage safely removed',r.reconciledLeakageRemoved],['Rows retained/protected',r.protectedLeakageRows],['Restored by refined context',r.restoredByRefinedContext],['Context role suggestions',r.contextRoleSuggestions],['Errors',r.errorCount],
      ['New tracked items',r.newResources],['Modified',r.modifiedResources],['Unchanged',r.unchangedResources],['Missing',r.missingResources],
      ['Tracked rows after',r.catalogueRowsAfter],['Learning catalogue after',r.learningCatalogueRowsAfter],['Learning included after',r.includedAfter],['Learning needs review after',r.reviewAfter],['Project artifacts after',r.projectArtifactRowsAfter],['Dual-lane resources after',r.dualLaneRowsAfter],['Excluded rows after',r.excludedAfter],['Exclusion records after',r.exclusionRecordsAfter],['Learning Collections',r.learningCollectionsAfter],['Collection-managed items',r.learningCollectionItemsAfter]
    ].map(([l,v])=>integrityMetric(l,v)).join('')}</div>${notes}${branches}<div class="scan-change-toolbar"><strong>What changed in this rescan?</strong><label>Show<select id="scanAuditChangeType"><option value="">All changes</option><option value="New">New</option><option value="Modified">Modified</option><option value="Missing">Missing</option><option value="NewlyExcluded">Newly excluded</option><option value="ReconciledRemoved">Reconciled leakage</option><option value="Restored">Restored</option><option value="LaneChanged">Lane changed</option></select></label><button id="refreshScanChanges" class="secondary-btn">Refresh changes</button><span id="scanAuditChangeCount" class="muted"></span></div><div id="scanAuditChangeList" class="scan-change-list"></div>`;
    $('scanAuditChangeType').addEventListener('change',loadLatestScanChanges);$('refreshScanChanges').addEventListener('click',loadLatestScanChanges);loadLatestScanChanges();
  }
  async function showLatestScanAudit(id,scroll=false){
    try{const r=await callHost('getLatestDiscoveryScanAudit',{sourceId:id});if(!r){toast('No rescan report has been recorded for this source yet.',true);return;}renderScanAudit(r);if(scroll)$('scanAuditPanel').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast(e.message,true);}
  }

  async function discover(id,button){const old=button.textContent;button.disabled=true;button.textContent='Rescanning…';try{const r=await callHost('discoverSource',{sourceId:id});const summary=await callHost('getDiscoveryReviewSummary',{sourceId:id});saveReviewOperation(id,{title:'Rescan source',resourcesFound:r.resourcesFound,policyExcludedFiles:r.policyExcludedFiles,restoredByRefinedContext:r.restoredByRefinedContext,learningCatalogueResources:r.learningCatalogueResources,projectArtifactResources:r.projectArtifactResources,dualLaneResources:r.dualLaneResources,lowValueProjectNoiseSkipped:r.lowValueProjectNoiseSkipped,contextRoleSuggestions:r.contextRoleSuggestions,pendingCount:summary.pendingCount,autoExcludedCount:summary.autoExcludedCount,collectionCount:summary.collectionCount,collectionManagedItemCount:summary.collectionManagedItemCount});toast(`Rescan complete: ${r.newFiles||0} new tracked, ${r.modifiedFiles||0} modified, ${r.unchangedFiles||0} unchanged; ${r.projectArtifactResources||0} project artifacts; ${r.lowValueProjectNoiseSkipped||0} low-value project items skipped; ${r.prunedBranches||0} context branch${Number(r.prunedBranches||0)===1?'':'es'} pruned.`);await loadSources();await loadDashboard();await showLatestScanAudit(id,true);if($('view-library').classList.contains('active'))await loadScannerPanel();}catch(e){toast(e.message,true);}finally{button.disabled=false;button.textContent=old;}}
  async function cleanIndex(id,button){if(!confirm('Apply the current discovery rules and your saved Include/Exclude choices to this source? Original files will not be changed or deleted.'))return;const old=button.textContent;button.disabled=true;button.textContent='Cleaning…';try{const r=await callHost('cleanLibraryIndex',{sourceId:id});const summary=await callHost('getDiscoveryReviewSummary',{sourceId:id});saveReviewOperation(id,{title:'Clean index',examined:r.examined,included:r.included,review:r.review,excluded:r.excluded,restored:r.restored,pendingCount:summary.pendingCount,autoExcludedCount:summary.autoExcludedCount,collectionCount:summary.collectionCount,collectionManagedItemCount:summary.collectionManagedItemCount});toast(`Checked ${r.examined}. Excluded ${r.excluded}; review ${r.review}; retained ${r.included}; restored ${r.restored}.`);await loadDashboard();await loadResources();await reviewDiscovery(id,'Pending',true);}catch(e){toast(e.message,true);}finally{button.disabled=false;button.textContent=old;}}

  function reviewStateLabel(state){return ({Pending:'needing review',Archives:'archives awaiting inspection',Collections:'Learning Collections',AutoExcluded:'automatically excluded',KeptExcluded:'manually excluded',Included:'manually included',All:'excluded/review records'})[state]||'review records';}
  function selectedReviewItems(){return [...document.querySelectorAll('.review-check:checked')].map(x=>activeReviewItems[Number(x.dataset.index)]).filter(Boolean);}
  function updateReviewSelection(){const selected=selectedReviewItems();$('selectedReviewCount').textContent=`${selected.length} selected`;['includeSelectedReview','excludeSelectedReview','addCollectionSelected','purgeSelectedReview'].forEach(id=>$(id).disabled=selected.length===0);const all=document.querySelectorAll('.review-check').length;const checked=selected.length;$('selectAllReview').checked=all>0&&checked===all;$('selectAllReview').indeterminate=checked>0&&checked<all;}
  function renderReviewItems(items,state,summary){activeReviewItems=items;const collectionMode=state==='Collections';$('reviewBulkBar').hidden=collectionMode;$('reviewSafetyNote').hidden=collectionMode;$('excludedList').hidden=collectionMode;if(collectionMode){const count=Number(summary?.collectionCount||0);const managed=Number(summary?.collectionManagedItemCount||0);$('excludedSummary').textContent=count?`${count} Learning Collection${count===1?'':'s'} detected, managing ${managed.toLocaleString()} indexed item${managed===1?'':'s'} as package content. Collection cards are shown below.`:'No Learning Collections are currently recorded for this source.';$('excludedList').innerHTML='';updateReviewSelection();return;}const total=Number(reviewStateTotal(summary,state)||0);$('excludedSummary').textContent=items.length?`Showing ${items.length}${total>items.length?` of ${total}`:''} ${reviewStateLabel(state)}${total>500?' (500 per view)':''}. Nothing here has been deleted from your drive.`:`No ${reviewStateLabel(state)} are currently recorded for this source.`;$('excludedList').innerHTML=items.length?items.map((x,i)=>`<article class="excluded-card ${x.isLearningCollectionCandidate?'collection-hint':''}"><label class="review-item-check"><input class="review-check" type="checkbox" data-index="${i}" ${(state==='Pending'||state==='Archives')&&['.zip','.rar','.7z'].includes(String(x.extension||'').toLowerCase())?'checked':''}><span></span></label><div class="excluded-main"><div class="review-title-row"><strong>${esc(x.fileName)}</strong>${x.overrideAction?`<span class="tag">Override: ${esc(x.overrideAction)}</span>`:''}${x.isLearningCollectionCandidate?'<span class="tag collection-tag">Learning Collection candidate</span>':''}</div><div class="path">${esc(x.sourceName)} / ${esc(x.relativePath)}</div></div><span class="tag reason-tag">${esc(x.discoveryReason)}</span></article>`).join(''):'';document.querySelectorAll('.review-check').forEach(x=>x.addEventListener('change',updateReviewSelection));updateReviewSelection();}
  function renderCollectionCandidates(items){$('collectionCandidateList').innerHTML=items.length?items.map(x=>`<article class="collection-candidate-card"><div><strong>${esc(x.displayName)}</strong><div class="path">${esc(x.sourceName)} / ${esc(x.rootRelativePath)}</div></div><div class="source-meta"><span class="tag">${esc(x.status)}</span><span class="tag">${Number(x.itemCount||0).toLocaleString()} indexed items</span></div></article>`).join(''):'<div class="empty compact-empty">No Learning Collection candidates saved yet.</div>';}
  async function loadCollectionCandidates(){if(!activeReviewSourceId)return [];try{const items=await callHost('getLearningCollectionCandidates',{sourceId:activeReviewSourceId});renderCollectionCandidates(items);return items;}catch(e){toast(e.message,true);return [];}}
  async function reviewDiscovery(id,state=null,scroll=false){try{activeReviewSourceId=id;const wanted=state||$('reviewState').value||'Pending';$('reviewState').value=wanted;const panel=$('excludedPanel');panel.hidden=false;restoreReviewOperation(id);const [summary,items,collections]=await Promise.all([callHost('getDiscoveryReviewSummary',{sourceId:id}),wanted==='Collections'?Promise.resolve([]):callHost('getDiscoveryReviewItems',{sourceId:id,state:wanted}),callHost('getLearningCollectionCandidates',{sourceId:id})]);renderReviewStats(summary);renderReviewItems(items,wanted,summary);renderCollectionCandidates(collections);if(scroll)panel.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast(e.message,true);}}
  async function applyReviewAction(action){const selected=selectedReviewItems();if(!selected.length||!activeReviewSourceId)return;const label=action==='Include'?'include in the active library':'keep excluded';if(!confirm(`${label[0].toUpperCase()+label.slice(1)} ${selected.length} selected item${selected.length===1?'':'s'}? This changes only WICareerBuilder's catalogue.`))return;try{const r=await callHost('applyDiscoveryOverride',{sourceId:activeReviewSourceId,action,relativePaths:selected.map(x=>x.relativePath)});toast(`${action}: ${r.updated} catalogue row${r.updated===1?'':'s'} updated${r.createdResources?`; ${r.createdResources} resource row${r.createdResources===1?'':'s'} created`:''}.`);await loadDashboard();await loadResources();await reviewDiscovery(activeReviewSourceId,$('reviewState').value);}catch(e){toast(e.message,true);}}
  async function purgeReviewSelected(){const selected=selectedReviewItems();if(!selected.length||!activeReviewSourceId)return;if(!confirm(`Purge ${selected.length} selected item${selected.length===1?'':'s'} from the active WICareerBuilder catalogue? REAL FILES ON YOUR DRIVE WILL NOT BE DELETED. Learning-linked resources are protected and will only be suppressed.`))return;try{const r=await callHost('purgeDiscoveryPaths',{sourceId:activeReviewSourceId,relativePaths:selected.map(x=>x.relativePath)});toast(`Processed ${r.updated}; purged ${r.purgedResources} active catalogue row${r.purgedResources===1?'':'s'}; protected ${r.protectedResources}. Files on disk were untouched.`);await loadDashboard();await loadResources();await reviewDiscovery(activeReviewSourceId,$('reviewState').value);}catch(e){toast(e.message,true);}}
  function commonParent(paths){if(!paths.length)return '';const dirs=paths.map(p=>String(p||'').replace(/\\/g,'/').split('/').slice(0,-1));let common=[...dirs[0]];for(const d of dirs.slice(1)){let n=0;while(n<common.length&&n<d.length&&common[n].toLowerCase()===d[n].toLowerCase())n++;common=common.slice(0,n);}return common.join('/');}
  async function addSelectedAsCollection(){const selected=selectedReviewItems();if(!selected.length||!activeReviewSourceId)return;let suggested=commonParent(selected.map(x=>x.relativePath));if(!suggested&&selected.length===1)suggested=String(selected[0].relativePath||'').replace(/\\/g,'/').split('/').slice(0,-1).join('/');const root=prompt('Learning Collection folder (relative to this library source). You can widen this from /glossary to the whole courseware folder if appropriate:',suggested);if(root===null||!root.trim())return;const parts=root.replace(/\\/g,'/').replace(/\/+$/,'').split('/');const defaultName=parts[parts.length-1]||'Learning Collection';const name=prompt('Name for this Learning Collection:',defaultName);if(name===null)return;try{const c=await callHost('addLearningCollectionCandidate',{sourceId:activeReviewSourceId,rootRelativePath:root.trim(),displayName:name.trim()||defaultName});toast(`Learning Collection candidate saved: ${c.displayName} (${c.itemCount} indexed items).`);await reviewDiscovery(activeReviewSourceId,$('reviewState').value);}catch(e){toast(e.message,true);}}
  async function rerunRules(){if(!activeReviewSourceId)return;if(!confirm('Re-apply the current discovery policy and saved manual choices to this source? Original files remain untouched.'))return;try{const sourceId=activeReviewSourceId;const r=await callHost('cleanLibraryIndex',{sourceId});const summary=await callHost('getDiscoveryReviewSummary',{sourceId});saveReviewOperation(sourceId,{title:'Re-run rules',examined:r.examined,included:r.included,review:r.review,excluded:r.excluded,restored:r.restored,pendingCount:summary.pendingCount,autoExcludedCount:summary.autoExcludedCount,collectionCount:summary.collectionCount,collectionManagedItemCount:summary.collectionManagedItemCount});toast('Rules re-applied. The full result is saved below.');await loadDashboard();await loadResources();await reviewDiscovery(sourceId,$('reviewState').value);}catch(e){toast(e.message,true);}}

  function analysisButton(r){const ext=String(r.extension||'').toLowerCase();const scanable=['.pdf','.docx','.pptx','.xlsx','.xlsm','.txt','.md','.csv','.html','.htm','.xml','.json','.doc','.ppt','.xls'].includes(ext);if(!scanable)return '';const analysed=['Analysed','Limited'].includes(r.analysisStatus);return `<button class="secondary-btn ${analysed?'view-analysis':'scan-resource'}" data-id="${r.id}">${analysed?'View scan':ext==='.pdf'?'Scan PDF':'Scan resource'}</button>`;}
  function organisationTags(r){const tags=[];if(r.courseLevel)tags.push(`<span class="tag">${esc(r.courseLevel)}</span>`);if(r.catalogueLane==='ProjectArtifact')tags.push('<span class="tag">Project artifact</span>');else if(r.catalogueLane==='Both')tags.push('<span class="tag">Learning + project</span>');if(r.learningSubject)tags.push(`<span class="tag organisation-learning">${esc(r.learningSubject)}</span>`);if(r.topic)tags.push(`<span class="tag organisation-topic">${esc(r.topic)}${r.subtopic?` › ${esc(r.subtopic)}`:''}</span>`);if(r.resourceType&&r.resourceType!=='Unknown')tags.push(`<span class="tag">${esc(r.resourceType)}</span>`);if(Number(r.relatedCopyCount||0)>0)tags.push(`<span class="tag duplicate-tag">${Number(r.relatedCopyCount)+1} copies</span>`);if(r.hasArchiveCompanion)tags.push('<span class="tag archive-companion-tag">Archive copy linked</span>');tags.push(`<span class="tag status-${esc(String(r.studyStatus||'Unsorted').toLowerCase().replace(/\s+/g,'-'))}">${esc(r.studyStatus||'Unsorted')}</span>`);return tags.join('');}
  function selectedResourceIds(){return [...document.querySelectorAll('.resource-check:checked')].map(x=>Number(x.dataset.id)).filter(Number.isFinite);}
  function updateResourceSelection(){const ids=selectedResourceIds();$('selectedResourceCount').textContent=`${ids.length} selected`;['bulkOrganise','bulkCreateStudy','bulkExtractLearning'].forEach(id=>{if($(id))$(id).disabled=ids.length===0;});$('bulkAssignRole').disabled=ids.length===0||!$('bulkRoleSelect').value;const all=document.querySelectorAll('.resource-check').length;const batch=Math.min(all,250);$('selectAllResources').checked=batch>0&&ids.length===batch;$('selectAllResources').indeterminate=ids.length>0&&ids.length<batch;}
  function resourceSelectionChanged(e){if(e?.target?.checked&&selectedResourceIds().length>250){e.target.checked=false;toast('A deliberate bulk batch is limited to 250 resources. Finish this batch, then select the next one.',true);}updateResourceSelection();}
  async function assignSelectedResourceRole(){const ids=selectedResourceIds();const roleKey=$('bulkRoleSelect').value;if(!ids.length||!roleKey)return;const button=$('bulkAssignRole'),old=button.textContent;button.disabled=true;button.textContent='Assigning…';try{const r=await callHost('assignResourceRole',{resourceIds:ids,roleKey,status:'Accepted'});toast(`Assigned ${r.roleLabel} to ${r.updated} resource${r.updated===1?'':'s'}.`);await loadRoleOptions();if($('view-roles').classList.contains('active'))await loadResourceRoles();}catch(e){toast(e.message,true);}finally{button.textContent=old;updateResourceSelection();}}
  function selectedScannerSourceId(){const value=$('scannerSourceFilter')?.value||'';return value?Number(value):null;}
  async function loadScannerPanel(){
    if(!$('scannerMetrics'))return;
    try{
      const current=$('scannerSourceFilter').value;
      const sources=(await callHost('getSources')).filter(s=>s.lifecycleStatus==='Active'&&s.isEnabled);
      $('scannerSourceFilter').innerHTML='<option value="">All active libraries</option>'+sources.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');
      if(current&&sources.some(s=>String(s.id)===current))$('scannerSourceFilter').value=current;
      await refreshScannerSummary();
      await loadLatestContentPlacement();
    }catch(e){$('scannerMetrics').innerHTML=`<span class="muted">${esc(e.message)}</span>`;}
  }
  async function refreshScannerSummary(){
    try{
      const sourceId=selectedScannerSourceId();
      const x=await callHost('getScannerSummary',sourceId?{sourceId}:{});
      const items=[['Included resources',x.totalResources],['New',x.newResources],['Modified',x.modifiedResources],['Unchanged',x.unchangedResources],['Missing',x.missingResources],['Structured analysis pending',x.analysisNeeded],['Fingerprint pending',x.fingerprintPending],['Fingerprinted',x.fingerprinted],['Duplicate candidate groups',x.duplicateFingerprintGroups]];
      $('scannerMetrics').innerHTML=items.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${Number(value||0).toLocaleString()}</strong></div>`).join('')+`<p class="scanner-last-scan muted">Last discovery: ${esc(fmtDate(x.lastScanUtc))}${Number(x.duplicateFingerprintResources||0)>0?` · ${Number(x.duplicateFingerprintResources).toLocaleString()} resources currently share a quick fingerprint`:''}</p>`;
    }catch(e){toast(e.message,true);}
  }
  async function runFingerprintScannerBatch(){
    const b=$('fingerprintScannerBatch'),old=b.textContent;b.disabled=true;b.textContent='Fingerprinting…';
    try{const sourceId=selectedScannerSourceId();const r=await callHost('fingerprintScannerBatch',sourceId?{sourceId,limit:100}:{limit:100});toast(`Fingerprinted ${r.fingerprinted} resource${r.fingerprinted===1?'':'s'}${r.duplicateFingerprintGroups?`; ${r.duplicateFingerprintGroups} duplicate candidate group${r.duplicateFingerprintGroups===1?'':'s'} detected`:''}.`);await refreshScannerSummary();}catch(e){toast(e.message,true);}finally{b.disabled=false;b.textContent=old;}
  }
  async function runAnalyseScannerBatch(){
    const b=$('analyseScannerBatch'),old=b.textContent;b.disabled=true;b.textContent='Analysing…';
    try{const sourceId=selectedScannerSourceId();const r=await callHost('analyseScannerBatch',sourceId?{sourceId,limit:25}:{limit:25});if(!r.requested)toast('No staged DOCX/PPTX/XLSX/text resources currently need analysis.');else toast(`Processed ${r.requested}: ${r.analysed} analysed, ${r.cached} cached, ${r.limited} limited, ${r.failed} failed. ${r.remaining} remain in this structured-content queue.`);await refreshScannerSummary();await loadResources();}catch(e){toast(e.message,true);}finally{b.disabled=false;b.textContent=old;}
  }


  function renderContentPlacementReport(r){
    const panel=$('contentPlacementReport');if(!panel)return;
    panel.hidden=false;
    const stats=[['Examined',r.examined],['Fingerprinted',r.fingerprinted],['Analysed',r.analysed],['Cached',r.cached],['Auto-organised',r.autoOrganised],['Partial hierarchy',r.partiallyOrganised],['Needs review',r.needsReview],['Protected existing',r.protectedExisting],['Limited',r.limited],['Failed',r.failed],['Remaining match',r.remainingMatching]];
    const route=x=>[x.learningSubject,x.topic,x.subtopic].filter(Boolean).join(' → ')||'No reliable placement';
    const confidence=x=>`<div class="placement-confidence-levels"><span class="tag">Subject ${Math.round(Number(x.subjectConfidence||0)*100)}%</span><span class="tag">Topic ${Math.round(Number(x.topicConfidence||0)*100)}%</span>${x.subtopic?`<span class="tag">Subtopic ${Math.round(Number(x.subtopicConfidence||0)*100)}%</span>`:''}</div>`;
    panel.innerHTML=`<div><p class="eyebrow">Content placement run #${Number(r.runId||0)}</p><h4>${r.focus?`Focus: ${esc(r.focus)}`:'Next structured resources'}</h4><p class="muted">Each hierarchy level must earn its own confidence. CareerBuilder may apply a confident subject/topic while leaving a weaker subtopic for review. Original files are unchanged.</p></div><div class="placement-stats">${stats.map(([l,v])=>`<div><span>${esc(l)}</span><strong>${Number(v||0).toLocaleString()}</strong></div>`).join('')}</div><div>${(r.items||[]).map(x=>`<article class="placement-item"><div><strong>${esc(x.fileName)}</strong><div class="placement-path">${esc(x.relativePath)}</div><div class="placement-route">${esc(route(x))}</div>${confidence(x)}<div class="placement-disposition">${esc(x.disposition)} · ${esc(x.analysisStatus)} · ${esc(x.reason)}</div></div><div class="placement-confidence"><span class="tag">${Math.round(Number(x.confidence||0)*100)}% path</span></div></article>`).join('')||'<div class="empty compact-empty">No matching structured Learning resources were found.</div>'}</div>`;
    panel.scrollIntoView({behavior:'smooth',block:'nearest'});
  }

  async function loadLatestContentPlacement(){
    const panel=$('contentPlacementReport');if(!panel)return;
    try{
      const sourceId=selectedScannerSourceId();
      const r=await callHost('getLatestContentPlacementRun',sourceId?{sourceId}:{});
      if(r)renderContentPlacementReport(r);else panel.hidden=true;
    }catch{panel.hidden=true;}
  }

  async function runContentPlacement(useFocus){
    const focus=useFocus?String($('contentPlacementFocus')?.value||'').trim():'';
    if(useFocus&&!focus){toast('Enter a focus such as “dc motor” first.',true);return;}
    const b=$(useFocus?'contentPlacementFocusButton':'contentPlacementNextButton'),old=b.textContent;
    b.disabled=true;b.textContent='Analysing + placing…';
    try{
      const sourceId=selectedScannerSourceId();
      const payload={limit:useFocus?50:25,focus};
      if(sourceId)payload.sourceId=sourceId;
      const r=await callHost('runContentPlacementBatch',payload);
      renderContentPlacementReport(r);
      toast(r.examined?`Placement run complete: ${r.autoOrganised} fully organised, ${r.partiallyOrganised||0} partial hierarchy, ${r.needsReview} need review, ${r.protectedExisting} protected.`:'No matching resources found.');
      knowledgeOverview=null;
      await refreshScannerSummary();
      await loadResources();
    }catch(e){toast(e.message,true);}
    finally{b.disabled=false;b.textContent=old;}
  }

  async function loadResources(){try{const items=await callHost('getResources',{search:$('searchBox').value,mediaKind:$('kindFilter').value,studyStatus:$('statusFilter').value,libraryKey:activeWorkspaceLibraryKey});resourcesById.clear();items.forEach(r=>resourcesById.set(Number(r.id),r));$('librarySummary').textContent=`${activeWorkspaceLibraryKey?`Knowledge/resource view: ${activeWorkspaceLibraryKey} · `:''}Showing ${items.length} resource${items.length===1?'':'s'} (maximum 500 per view; batch actions use up to 250). Organising and assigning roles changes only CareerBuilder's catalogue.`;$('resourceList').innerHTML=items.length?items.map(r=>`<article class="resource-card ${r.isAvailable?'':'unavailable'}"><label class="resource-select" title="Select ${esc(r.fileName)}"><input class="resource-check" type="checkbox" data-id="${r.id}" aria-label="Select ${esc(r.fileName)}"></label><div><h3>${esc(r.fileName)}</h3><div class="resource-meta"><span class="tag">${esc(r.mediaKind)}</span><span class="tag">${esc(r.subject||'Unassigned')}</span>${organisationTags(r)}<span class="tag">${fmtSize(r.sizeBytes)}</span><span class="tag">${r.isAvailable?'Available':'Source unavailable'}</span><span class="tag analysis-${esc(String(r.analysisStatus).toLowerCase())}">${esc(r.analysisStatus)}</span></div><div class="path">${esc(r.sourceName)} / ${esc(r.relativePath)}</div></div><div class="resource-actions"><button class="secondary-btn open-resource" data-id="${r.id}" ${r.isAvailable?'':'disabled'}>Open</button><button class="secondary-btn organise-resource" data-id="${r.id}">Organise</button>${r.isAvailable?analysisButton(r):''}</div></article>`).join(''):'<div class="empty">Nothing matched. Add/discover a source or change the filters.</div>';
      document.querySelectorAll('.resource-check').forEach(x=>x.addEventListener('change',resourceSelectionChanged));
      updateResourceSelection();
      document.querySelectorAll('.open-resource').forEach(b=>b.addEventListener('click',async()=>{try{await callHost('openResource',{resourceId:Number(b.dataset.id)});}catch(e){toast(e.message,true);}}));
      document.querySelectorAll('.organise-resource').forEach(b=>b.addEventListener('click',()=>openOrganisation(Number(b.dataset.id),false,true)));
      document.querySelectorAll('.scan-resource').forEach(b=>b.addEventListener('click',()=>scanResource(Number(b.dataset.id),b)));
      document.querySelectorAll('.view-analysis').forEach(b=>b.addEventListener('click',()=>viewAnalysis(Number(b.dataset.id))));
    }catch(e){toast(e.message,true);}}

  async function scanResource(id,button){const old=button?.textContent;if(button){button.disabled=true;button.textContent='Scanning…';}try{const a=await callHost('scanResource',{resourceId:id});showAnalysis(id,a);await loadResources();await loadDashboard();if(a.analysisStatus==='Failed')toast(a.errorMessage||'PDF scan failed.',true);else toast('Resource scan complete.');}catch(e){toast(e.message,true);}finally{if(button){button.disabled=false;button.textContent=old;}}}
  async function viewAnalysis(id){try{const a=await callHost('getResourceAnalysis',{resourceId:id});if(!a){toast('No saved scan exists yet.',true);return;}showAnalysis(id,a);}catch(e){toast(e.message,true);}}
  function tagList(items,empty='None detected'){return items?.length?`<div class="analysis-tags">${items.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>`:`<p class="muted">${esc(empty)}</p>`;}
  function showAnalysis(id,a){activeAnalysisResourceId=id;const r=resourcesById.get(Number(id));$('analysisTitle').textContent=a.documentTitle||r?.fileName||'Resource analysis';$('analysisSubtitle').textContent=`${a.scannerKind} · scanned ${fmtDate(a.scannedUtc)}`;
    const searchable=a.hasSearchableText?'Searchable text detected':'Little/no extractable text detected';
    const sampleNote=a.pageCount?`${a.pagesSampled} of ${a.pageCount} pages sampled`:`${a.pagesSampled} pages sampled`;
    $('analysisBody').innerHTML=a.analysisStatus==='Failed'?`<div class="analysis-warning"><strong>Scan failed</strong><p>${esc(a.errorMessage||'Unknown PDF scan error.')}</p></div>`:`
      <div class="analysis-grid">
        <div class="analysis-stat"><span>Subject</span><strong>${esc(r?.subject||'Unassigned')}</strong><small>Inherited from library source</small></div>
        <div class="analysis-stat"><span>Content focus</span><strong>${esc(a.suggestedTopic||'Unclassified')}</strong><small>Suggestion only; it is never applied automatically</small></div>
        <div class="analysis-stat"><span>Suggested type</span><strong>${esc(a.suggestedResourceType)}</strong></div>
        <div class="analysis-stat"><span>Pages</span><strong>${a.pageCount??'Unknown'}</strong><small>${esc(sampleNote)}</small></div>
        <div class="analysis-stat"><span>Text</span><strong>${esc(searchable)}</strong><small>${Number(a.extractedCharacters||0).toLocaleString()} sampled characters</small></div>
        <div class="analysis-stat"><span>Author metadata</span><strong>${esc(a.author||'Not supplied')}</strong></div>
      </div>
      ${!a.hasSearchableText?'<div class="analysis-warning"><strong>Little/no searchable text was extracted.</strong><p>The current scanner could not extract enough text. Image-only PDFs still need OCR later; legacy DOC/PPT/XLS formats use limited metadata classification until a safe reader is added.</p></div>':''}
      <section class="analysis-section"><h3>Suggested subtopics</h3>${tagList(a.suggestedSubtopics,'No reliable subtopic suggestions yet.')}</section>
      <section class="analysis-section"><h3>Possible useful content</h3>${tagList(a.contentIndicators,'No strong content indicators were detected in the sampled pages.')}</section>
      <section class="analysis-section"><h3>Frequent useful terms</h3>${tagList(a.keywords,'No reliable keywords extracted.')}</section>
      <section class="analysis-section"><h3>Possible headings</h3>${a.headings?.length?`<ul class="heading-list">${a.headings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="muted">No reliable heading candidates detected.</p>'}</section>
      <section class="analysis-section"><h3>Sampled text preview</h3><pre class="text-preview">${esc(a.textPreview||'No extractable text.')}</pre></section>
      <div class="analysis-note"><strong>What this scan means</strong><p>This is selected-resource analysis, not a background drive scan. It may be a bounded sample and suggestions remain reviewable before organisation or any future output creation.</p></div>`;
    $('analysisModal').classList.add('open');$('analysisModal').setAttribute('aria-hidden','false');}
  function closeAnalysis(){$('analysisModal').classList.remove('open');$('analysisModal').setAttribute('aria-hidden','true');activeAnalysisResourceId=null;}
  document.querySelectorAll('[data-close-analysis]').forEach(x=>x.addEventListener('click',closeAnalysis));
  $('rescanResource').addEventListener('click',()=>{if(activeAnalysisResourceId)scanResource(activeAnalysisResourceId,$('rescanResource'));});
  $('organiseFromAnalysis').addEventListener('click',()=>{const id=activeAnalysisResourceId;if(!id)return;closeAnalysis();openOrganisation(id,true);});

  function ensureSelectOption(select,value){if(!value)return;if(!Array.from(select.options).some(o=>o.value===value)){const o=document.createElement('option');o.value=value;o.textContent=value;select.appendChild(o);}select.value=value;}
  async function openOrganisation(id,preferScan=false,autoScanSelected=false){activeOrganisationResourceId=id;activeOrganisationAnalysis=null;let r=resourcesById.get(Number(id));try{if(autoScanSelected&&r&&r.isAvailable&&!['Analysed','Limited'].includes(r.analysisStatus)&&String(r.extension||'').toLowerCase()!=='.pdf'&&['.docx','.pptx','.xlsx','.xlsm','.txt','.md','.csv','.html','.htm','.xml','.json','.doc','.ppt','.xls'].includes(String(r.extension||'').toLowerCase())){const a=await callHost('scanResource',{resourceId:id});activeOrganisationAnalysis=a;r={...r,analysisStatus:a.analysisStatus};resourcesById.set(Number(id),r);}const org=await callHost('getResourceOrganisation',{resourceId:id});const workspace=await callHost('getWorkspaceOverview',{courseLevel:org.courseLevel||r?.courseLevel||'ONC'});$('learningSubjectOptions').innerHTML=(workspace.subjects||[]).map(x=>`<option value="${esc(x.name)}"></option>`).join('');$('organisationTitle').textContent=r?.fileName||'Resource';$('organisationPath').textContent=r?`${r.sourceName} / ${r.relativePath}`:'';$('organisationSubject').value=org.subject||r?.subject||'Unassigned';$('organisationCourseLevel').value=org.courseLevel||r?.courseLevel||'';$('organisationLearningSubject').value=org.learningSubject||'';$('organisationTopic').value=org.topic||'';$('organisationSubtopic').value=org.subtopic||'';ensureSelectOption($('organisationType'),org.resourceType||'Unknown');$('organisationStatus').value=org.studyStatus||'Unsorted';$('organisationNotes').value=org.notes||'';
      const suggestion=$('scanSuggestion');suggestion.hidden=true;suggestion.innerHTML='';
      if(r&&['Analysed','Limited'].includes(r.analysisStatus)){
        try{const a=await callHost('getResourceAnalysis',{resourceId:id});if(a&&['Analysed','Limited'].includes(a.analysisStatus)){activeOrganisationAnalysis=a;suggestion.hidden=false;suggestion.innerHTML=`<strong>Saved resource scan suggestions</strong><p>${esc(a.suggestedTopic||'No topic suggestion')}${a.suggestedSubtopics?.length?` → ${esc(a.suggestedSubtopics[0])}`:''} · ${esc(a.suggestedResourceType||'Unknown type')}</p><button id="useScanSuggestions" class="secondary-btn" type="button">Use these suggestions</button>`;setTimeout(()=>{$('useScanSuggestions')?.addEventListener('click',applyScanSuggestions);},0);if(preferScan&&!(org.learningSubject||org.topic||org.subtopic)&&org.resourceType==='Unknown')applyScanSuggestions();}}catch{/* Saved organisation remains fully usable if analysis cannot be loaded. */}
      }
      $('organisationModal').classList.add('open');$('organisationModal').setAttribute('aria-hidden','false');
    }catch(e){activeOrganisationResourceId=null;toast(e.message,true);}}
  function learningSubjectFromScan(topic){const map={'Mathematics':'Engineering Mathematics','Engineering Mathematics':'Engineering Mathematics','Electrical':'Electrical Principles','Electrical Principles':'Electrical Principles','Electronics':'Electronics','Components':'Components','Electrical Machines':'Electrical Machines','Communications / RF':'RF & Communications','RF & Communications':'RF & Communications','Control / PLC':'PLC & Control','PLC & Control':'PLC & Control','Measurement & Testing':'Test & Measurement','Test & Measurement':'Test & Measurement','Health & Safety':'Health & Safety','Projects':'Projects','Mechanical':'Mechanical Engineering','General Engineering / Reference':'','General Engineering':''};return map[topic]||topic||'';}
  function applyScanSuggestions(){const a=activeOrganisationAnalysis;if(!a)return;const learning=learningSubjectFromScan(a.suggestedTopic);if(learning)$('organisationLearningSubject').value=learning;if(a.suggestedSubtopics?.length)$('organisationTopic').value=a.suggestedSubtopics[0];if(a.suggestedSubtopics?.length>1)$('organisationSubtopic').value=a.suggestedSubtopics[1];if(a.suggestedResourceType)ensureSelectOption($('organisationType'),a.suggestedResourceType);}
  function closeOrganisation(){$('organisationModal').classList.remove('open');$('organisationModal').setAttribute('aria-hidden','true');activeOrganisationResourceId=null;activeOrganisationAnalysis=null;}
  document.querySelectorAll('[data-close-organisation]').forEach(x=>x.addEventListener('click',closeOrganisation));
  $('saveOrganisation').addEventListener('click',async()=>{if(!activeOrganisationResourceId)return;const button=$('saveOrganisation');const old=button.textContent;button.disabled=true;button.textContent='Saving…';try{await callHost('saveResourceOrganisation',{resourceId:activeOrganisationResourceId,learningSubject:$('organisationLearningSubject').value.trim(),topic:$('organisationTopic').value.trim(),subtopic:$('organisationSubtopic').value.trim(),resourceType:$('organisationType').value,studyStatus:$('organisationStatus').value,notes:$('organisationNotes').value.trim()});closeOrganisation();await loadResources();toast('Resource organisation saved.');}catch(e){toast(e.message,true);}finally{button.disabled=false;button.textContent=old;}});


