  async function loadLearningModules(){
    try{
      const [modules,issues,comparisons]=await Promise.all([callHost('getLearningModules'),callHost('getStudyClassificationIssues'),callHost('getPendingBlockComparisons')]);
      activeClassificationIssues=issues||[];activeBlockComparisons=comparisons||[];
      $('classificationIssueCount').textContent=activeClassificationIssues.length;
      $('blockComparisonCount').textContent=activeBlockComparisons.length;
      $('moduleList').innerHTML=modules.length?modules.map(m=>`<article class="module-card ${Number(m.id)===activeLearningModuleId?'selected':''}" data-id="${m.id}"><div><p class="eyebrow">${esc(m.subject||'Subject')} ${m.courseLevel?`· ${esc(m.courseLevel)}`:''}</p><h3>${esc(m.title)}</h3><div class="resource-meta">${m.learningSubject?`<span class="tag organisation-learning">${esc(m.learningSubject)}</span>`:''}${m.topic?`<span class="tag organisation-topic">${esc(m.topic)}${m.subtopic?` › ${esc(m.subtopic)}`:''}</span>`:''}<span class="tag">${m.blockCount} block${m.blockCount===1?'':'s'}</span><span class="tag">${esc(m.status)}</span></div>${m.primaryResourceName?`<div class="path">Source: ${esc(m.primaryResourceName)}</div>`:''}</div><button class="secondary-btn open-module" data-id="${m.id}">Open</button></article>`).join(''):'<div class="empty">No v0.5 prototype study modules are stored. New v0.6 lesson creation will be handled by Lesson Factory rather than this legacy screen.</div>';
      document.querySelectorAll('.open-module').forEach(b=>b.addEventListener('click',()=>openLearningModule(Number(b.dataset.id))));
    }catch(e){toast(e.message,true);}
  }

  function classificationIssueCard(x){return `<article class="candidate-card"><label class="candidate-check"><input class="classification-check" type="checkbox" data-id="${x.moduleId}"><span></span></label><div><p class="eyebrow">${esc(x.primaryResourceName||'Study Builder lesson')}</p><h3>${esc(x.moduleTitle)}</h3><div class="classification-compare-grid"><div><strong>Current</strong><span>${esc([x.currentLearningSubject,x.currentTopic,x.currentSubtopic].filter(Boolean).join(' › ')||'Unclassified')}</span></div><div><strong>Suggested</strong><span>${esc([x.suggestedLearningSubject,x.suggestedTopic,x.suggestedSubtopic].filter(Boolean).join(' › '))}</span></div></div>${x.suggestedTitle!==x.moduleTitle?`<p class="muted">Suggested lesson title: <strong>${esc(x.suggestedTitle)}</strong></p>`:''}<p class="muted">${esc(x.reason)}</p><div class="candidate-context"><span class="tag">${Number(x.linkedResourceCount||0)} linked source${Number(x.linkedResourceCount||0)===1?'':'s'}</span></div></div></article>`;}
  function selectedClassificationIds(){return [...document.querySelectorAll('.classification-check:checked')].map(x=>Number(x.dataset.id)).filter(Boolean);}
  function updateClassificationSelection(){const ids=selectedClassificationIds();$('selectedClassificationCount').textContent=`${ids.length} selected`;$('applyClassificationRepairs').disabled=!ids.length;const all=[...document.querySelectorAll('.classification-check')];$('selectAllClassificationIssues').checked=!!all.length&&ids.length===all.length;}
  async function openClassificationReview(){try{activeClassificationIssues=await callHost('getStudyClassificationIssues');$('classificationIssueList').innerHTML=activeClassificationIssues.length?activeClassificationIssues.map(classificationIssueCard).join(''):'<div class="empty">No contradictory Study Builder classifications were detected.</div>';document.querySelectorAll('.classification-check').forEach(x=>x.addEventListener('change',updateClassificationSelection));$('selectAllClassificationIssues').checked=false;$('classificationRepairStatus').textContent='';updateClassificationSelection();$('classificationModal').classList.add('open');$('classificationModal').setAttribute('aria-hidden','false');}catch(e){toast(e.message,true);}}
  function closeClassificationReview(){$('classificationModal').classList.remove('open');$('classificationModal').setAttribute('aria-hidden','true');}
  async function applyClassificationRepairs(){const ids=selectedClassificationIds();if(!ids.length)return;if(!confirm(`Apply ${ids.length} selected classification repair${ids.length===1?'':'s'}? This updates only WICareerBuilder's database; original files are untouched.`))return;const b=$('applyClassificationRepairs'),old=b.textContent,status=$('classificationRepairStatus');b.disabled=true;b.textContent='Repairing…';status.textContent='Applying database repairs…';try{const r=await callHost('applyStudyClassificationRepairs',{moduleIds:ids});const merged=Number(r.mergedCandidates||0);const message=`Repaired ${r.updatedModules} lesson${r.updatedModules===1?'':'s'}; ${r.updatedCandidates} candidates realigned${merged?`, ${merged} exact candidate duplicate${merged===1?'':'s'} safely merged`:''}; ${r.updatedResources} organised resources aligned.`;status.textContent=message;toast(message);closeClassificationReview();await loadLearningModules();await loadWorkspace();if(activeLearningModuleId)await openLearningModule(activeLearningModuleId);}catch(e){status.textContent=`Repair failed: ${e.message}`;toast(`Repair failed: ${e.message}`,true);}finally{b.disabled=false;b.textContent=old;}}

  function blockComparisonCard(x){const pct=Math.round(Number(x.similarity||0)*100);return `<article class="candidate-card comparison-card"><div><p class="eyebrow">${esc(x.moduleTitle)} · ${esc(x.candidateType)}</p><h3>${esc(x.candidateTitle||'Learning candidate')}</h3><div class="block-compare-grid"><div><strong>New candidate</strong><p>${esc(x.candidateText)}</p></div><div><strong>Existing block · ${pct}% similar</strong><p>${esc(x.existingBlockText)}</p></div></div><div class="candidate-context"><span class="tag">${Number(x.candidateSourceCount||0)} source${Number(x.candidateSourceCount||0)===1?'':'s'}</span><span class="tag">${esc(x.existingBlockType)}</span></div><div class="candidate-actions"><button class="primary-btn comparison-use-existing" data-id="${x.id}">Use existing</button><button class="secondary-btn comparison-keep-both" data-id="${x.id}">Keep both</button><button class="danger-btn comparison-reject" data-id="${x.id}">Reject candidate</button></div></div></article>`;}
  async function loadBlockComparisons(){activeBlockComparisons=await callHost('getPendingBlockComparisons');$('blockComparisonCount').textContent=activeBlockComparisons.length;$('blockComparisonList').innerHTML=activeBlockComparisons.length?activeBlockComparisons.map(blockComparisonCard).join(''):'<div class="empty">No block similarities are waiting for comparison.</div>';document.querySelectorAll('.comparison-use-existing').forEach(b=>b.addEventListener('click',()=>resolveBlockComparison(Number(b.dataset.id),'UseExisting')));document.querySelectorAll('.comparison-keep-both').forEach(b=>b.addEventListener('click',()=>resolveBlockComparison(Number(b.dataset.id),'KeepBoth')));document.querySelectorAll('.comparison-reject').forEach(b=>b.addEventListener('click',()=>resolveBlockComparison(Number(b.dataset.id),'RejectCandidate')));}
  async function openBlockComparisonReview(){try{await loadBlockComparisons();$('blockComparisonModal').classList.add('open');$('blockComparisonModal').setAttribute('aria-hidden','false');}catch(e){toast(e.message,true);}}
  function closeBlockComparisonReview(){$('blockComparisonModal').classList.remove('open');$('blockComparisonModal').setAttribute('aria-hidden','true');}
  async function resolveBlockComparison(id,action){const wording=action==='UseExisting'?"reuse the existing block and add this candidate's source links":action==='KeepBoth'?'keep both learning blocks':'reject this extracted candidate';if(!confirm(`Confirm: ${wording}?`))return;try{const r=await callHost('resolveBlockComparison',{comparisonId:id,action});toast(r.message);await loadBlockComparisons();await loadLearningModules();await loadCandidates();if(activeLearningModuleId)await openLearningModule(activeLearningModuleId);}catch(e){toast(e.message,true);}}

  async function openLearningModule(moduleId){
    try{
      const m=await callHost('getLearningModule',{moduleId});
      activeLearningModuleId=Number(m.id);activeLearningModule=m;
      renderLearningWorkspace(m);await loadLearningModules();
    }catch(e){toast(e.message,true);}
  }

  function sourceLabel(source){
    if(!source)return '';
    const bits=[source.resourceName];
    if(source.pageNumber)bits.push(source.endPageNumber&&source.endPageNumber!==source.pageNumber?`pages ${source.pageNumber}–${source.endPageNumber}`:`page ${source.pageNumber}`);
    if(source.timestampSeconds!=null)bits.push(formatTimestamp(source.timestampSeconds));
    return bits.join(' · ');
  }
  function formatTimestamp(seconds){const n=Math.max(0,Number(seconds||0));const h=Math.floor(n/3600),m=Math.floor((n%3600)/60),s=Math.floor(n%60);return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`;}
  function blockTypeLabel(type){return ({WorkedExample:'Worked example',PracticeQuestion:'Practice question'})[type]||type;}

  function renderLearningBlock(block){
    const sources=block.sources||[];
    const sourceHtml=sources.length?`<div class="learning-sources">${sources.map(src=>`<button class="source-link" data-resource="${src.resourceId}" data-page="${src.pageNumber??''}" data-time="${src.timestampSeconds??''}">Source · ${esc(sourceLabel(src))}</button>${src.note?`<span>${esc(src.note)}</span>`:''}`).join('')}</div>`:'';
    const formula=block.formula?`<div class="formula-display">${esc(block.formula)}</div>`:'';
    const body=block.body?`<p class="learning-body">${esc(block.body)}</p>`:'';
    const head=`<div class="learning-block-head"><span class="pill">${esc(blockTypeLabel(block.blockType))}</span><div class="learning-block-actions"><button class="text-btn edit-block" data-id="${block.id}">Edit</button><button class="text-btn delete-block" data-id="${block.id}">Remove</button></div></div>`;
    if(block.blockType==='PracticeQuestion'||block.blockType==='Checkpoint'){
      const answerReady=block.answerKind&&block.answerKind!=='None'&&String(block.expectedAnswer||'').trim()!=='';
      const interaction=answerReady?`<div class="answer-row"><input class="learner-answer" data-block="${block.id}" placeholder="Your answer…"><button class="primary-btn check-answer" data-id="${block.id}">Check</button></div><div class="answer-result" id="answerResult-${block.id}"></div>`:`<div class="draft-question-note"><strong>Draft question</strong><span>Add an expected answer, hint and worked explanation before using this as an interactive checked question.</span></div>`;
      return `<article class="learning-block question-block" data-block="${block.id}">${head}<h4>${esc(block.title||'Try this')}</h4>${body}${formula}<div class="question-prompt">${esc(block.prompt||'')}</div>${interaction}<div class="learning-reveal-row">${block.hint?`<button class="secondary-btn reveal-hint" data-id="${block.id}">Hint</button>`:''}${block.explanation?`<button class="secondary-btn reveal-explanation" data-id="${block.id}">Show worked explanation</button>`:''}</div>${block.hint?`<div class="reveal-box" id="hint-${block.id}" hidden><strong>Hint</strong><p>${esc(block.hint)}</p></div>`:''}${block.explanation?`<div class="reveal-box" id="explanation-${block.id}" hidden><strong>Worked explanation</strong><p>${esc(block.explanation)}</p></div>`:''}${sourceHtml}</article>`;
    }
    return `<article class="learning-block" data-block="${block.id}">${head}<h4>${esc(block.title||blockTypeLabel(block.blockType))}</h4>${body}${formula}${block.prompt?`<div class="question-prompt">${esc(block.prompt)}</div>`:''}${block.explanation?`<div class="worked-explanation"><strong>Why / method</strong><p>${esc(block.explanation)}</p></div>`:''}${sourceHtml}</article>`;
  }

  function renderLearningWorkspace(m){
    const breadcrumb=[m.subject,m.courseLevel,m.learningSubject,m.topic,m.subtopic].filter(Boolean).map(esc).join(' › ');
    $('moduleWorkspace').classList.remove('empty-workspace');
    $('moduleWorkspace').innerHTML=`<div class="module-workspace-head"><div><p class="eyebrow">${breadcrumb||'Learning module'}</p><h3>${esc(m.title)}</h3>${m.primaryResourceName?`<p class="muted">Primary source: ${esc(m.primaryResourceName)}</p>`:''}</div><button id="addLearningBlock" class="primary-btn">Add learning block</button></div>
      <div class="module-meta-grid"><label>Title<input id="moduleTitle" value="${esc(m.title)}"></label><label>Status<select id="moduleStatus"><option${m.status==='Draft'?' selected':''}>Draft</option><option${m.status==='Ready'?' selected':''}>Ready</option><option${m.status==='Archived'?' selected':''}>Archived</option></select></label><label>Learning subject<input id="moduleLearningSubject" value="${esc(m.learningSubject||'')}"></label><label>Topic<input id="moduleTopic" value="${esc(m.topic||'')}"></label><label>Subtopic<input id="moduleSubtopic" value="${esc(m.subtopic||'')}"></label></div>
      <label class="organisation-notes">Module purpose / summary<textarea id="moduleSummary" rows="3">${esc(m.summary||'')}</textarea></label><div class="module-actions"><button id="saveLearningModule" class="secondary-btn">Save module details</button></div>
      <div class="study-principle"><strong>Teach the route, not just the result.</strong><span>Use explanations, formulas, worked examples, hints and practice. Link blocks to the exact source page or video timestamp whenever you can.</span></div>
      <div id="learningBlocks" class="learning-blocks">${m.blocks?.length?m.blocks.map(renderLearningBlock).join(''):'<div class="empty">No learning blocks yet. Add an explanation, formula, worked example or practice question.</div>'}</div>`;
    $('addLearningBlock').addEventListener('click',openBlockModal);
    $('saveLearningModule').addEventListener('click',saveLearningModule);
    document.querySelectorAll('.edit-block').forEach(b=>b.addEventListener('click',()=>openBlockModal(Number(b.dataset.id))));
    document.querySelectorAll('.delete-block').forEach(b=>b.addEventListener('click',()=>deleteLearningBlock(Number(b.dataset.id))));
    document.querySelectorAll('.check-answer').forEach(b=>b.addEventListener('click',()=>checkLearningAnswer(Number(b.dataset.id))));
    document.querySelectorAll('.reveal-hint').forEach(b=>b.addEventListener('click',()=>{const e=$(`hint-${b.dataset.id}`);e.hidden=!e.hidden;}));
    document.querySelectorAll('.reveal-explanation').forEach(b=>b.addEventListener('click',()=>{const e=$(`explanation-${b.dataset.id}`);e.hidden=!e.hidden;}));
    document.querySelectorAll('.source-link').forEach(b=>b.addEventListener('click',()=>openLearningSource(b)));
  }

  async function saveLearningModule(){if(!activeLearningModuleId)return;try{const m=await callHost('updateLearningModule',{moduleId:activeLearningModuleId,title:$('moduleTitle').value.trim(),summary:$('moduleSummary').value.trim(),learningSubject:$('moduleLearningSubject').value.trim(),topic:$('moduleTopic').value.trim(),subtopic:$('moduleSubtopic').value.trim(),status:$('moduleStatus').value});activeLearningModule=m;renderLearningWorkspace(m);await loadLearningModules();toast('Learning module saved.');}catch(e){toast(e.message,true);}}

  function setBlockSourceFieldsDisabled(disabled){['blockSourcePage','blockSourceEndPage','blockSourceTimestamp','blockSourceNote'].forEach(id=>$(id).disabled=disabled);}
  function openBlockModal(blockId=null){if(!activeLearningModule)return;activeLearningBlockId=blockId?Number(blockId):null;const block=activeLearningBlockId?(activeLearningModule.blocks||[]).find(x=>Number(x.id)===activeLearningBlockId):null;$('blockModalTitle').textContent=block?'Edit study activity':'Add study activity';$('saveLearningBlock').textContent=block?'Save changes':'Add block';$('blockType').value=block?.blockType||'Explanation';$('blockTitle').value=block?.title||'';$('blockBody').value=block?.body||'';$('blockFormula').value=block?.formula||'';$('blockPrompt').value=block?.prompt||'';$('blockAnswerKind').value=block?.answerKind||'None';$('blockExpectedAnswer').value=block?.expectedAnswer||'';$('blockTolerance').value=block?.numericTolerance??'';$('blockHint').value=block?.hint||'';$('blockExplanation').value=block?.explanation||'';const source=block?.sources?.[0];$('blockSourcePage').value=source?.pageNumber??'';$('blockSourceEndPage').value=source?.endPageNumber??'';$('blockSourceTimestamp').value=source?.timestampSeconds??'';$('blockSourceNote').value=source?.note||'';setBlockSourceFieldsDisabled(!!block);$('blockModal').classList.add('open');$('blockModal').setAttribute('aria-hidden','false');}
  function closeBlockModal(){$('blockModal').classList.remove('open');$('blockModal').setAttribute('aria-hidden','true');activeLearningBlockId=null;setBlockSourceFieldsDisabled(false);}
  document.querySelectorAll('[data-close-block]').forEach(x=>x.addEventListener('click',closeBlockModal));
  $('saveLearningBlock').addEventListener('click',async()=>{if(!activeLearningModule)return;const num=v=>{const t=String(v||'').trim();return t===''?null:Number(t);};const payload={moduleId:activeLearningModule.id,blockType:$('blockType').value,title:$('blockTitle').value.trim(),body:$('blockBody').value.trim(),formula:$('blockFormula').value.trim(),prompt:$('blockPrompt').value.trim(),answerKind:$('blockAnswerKind').value,expectedAnswer:$('blockExpectedAnswer').value.trim(),numericTolerance:num($('blockTolerance').value),hint:$('blockHint').value.trim(),explanation:$('blockExplanation').value.trim()};try{if(activeLearningBlockId){await callHost('updateLearningBlock',{...payload,blockId:activeLearningBlockId});}else{await callHost('addLearningBlock',{...payload,sourceResourceId:activeLearningModule.primaryResourceId,sourcePageNumber:num($('blockSourcePage').value),sourceEndPageNumber:num($('blockSourceEndPage').value),sourceTimestampSeconds:num($('blockSourceTimestamp').value),sourceNote:$('blockSourceNote').value.trim()});}const edited=!!activeLearningBlockId;closeBlockModal();await openLearningModule(activeLearningModule.id);toast(edited?'Learning block updated.':'Learning block added.');}catch(e){toast(e.message,true);}});
  async function deleteLearningBlock(blockId){try{await callHost('deleteLearningBlock',{blockId});await openLearningModule(activeLearningModuleId);toast('Learning block removed.');}catch(e){toast(e.message,true);}}
  async function checkLearningAnswer(blockId){const input=document.querySelector(`.learner-answer[data-block="${blockId}"]`);const result=$(`answerResult-${blockId}`);try{const r=await callHost('checkLearningAnswer',{blockId,answer:input?.value||''});result.textContent=r.message;result.className=`answer-result ${r.isCorrect?'correct':'incorrect'}`;}catch(e){toast(e.message,true);}}
  async function openLearningSource(button){try{await callHost('openLearningSource',{resourceId:Number(button.dataset.resource),pageNumber:button.dataset.page?Number(button.dataset.page):null,timestampSeconds:button.dataset.time?Number(button.dataset.time):null});}catch(e){toast(e.message,true);}}
