  async function reconnectLibrary(id){try{const picked=await callHost('pickFolder');if(!picked.path)return;if(!confirm(`Reconnect this Library to:\n${picked.path}\n\nThis changes only WICareerBuilder's source path. Original files are not moved or changed.`))return;const r=await callHost('reconnectLibrary',{sourceId:id,path:picked.path});toast(r.message);await loadSources();await loadResources();await loadDashboard();}catch(e){toast(e.message,true);}}
  async function setSourceEnabled(id,enabled){try{await callHost('setLibraryEnabled',{sourceId:id,enabled});toast(enabled?'Library enabled.':'Library disabled. Resources remain in the catalogue.');await loadSources();await loadDashboard();}catch(e){toast(e.message,true);}}
  async function removeLibrary(id){if(!confirm('Remove this Library from active WICareerBuilder views? ORIGINAL FILES ON THE DRIVE WILL NOT BE DELETED. The catalogue entry is kept in Recently Removed so it can be restored.'))return;try{const r=await callHost('removeLibrary',{sourceId:id});toast(r.message);await loadSources();await loadResources();await loadDashboard();}catch(e){toast(e.message,true);}}
  async function restoreLibrary(id){try{await callHost('restoreLibrary',{sourceId:id});toast('Library restored.');await loadSources();await loadDashboard();}catch(e){toast(e.message,true);}}
  async function purgeLibrary(id){if(!confirm('Permanently purge this removed Library from WICareerBuilder catalogue data? ORIGINAL DRIVE FILES WILL STILL NOT BE DELETED. This is only allowed when no learning material still references the Library.'))return;try{const r=await callHost('purgeLibrary',{sourceId:id});toast(r.message);await loadSources();await loadDashboard();}catch(e){toast(e.message,true);}}

  async function loadWorkspace(){try{const [w,c,k]=await Promise.all([callHost('getWorkspaceOverview',{courseLevel:'ONC'}),callHost('getCandidateReviewSummary',{courseLevel:'ONC'}),callHost('getKnowledgeWorkbenchOverview')]);$('workspaceCourseTitle').textContent=`${w.knowledgeArea} → ${w.courseName}`;$('learningSubjectOptions').innerHTML=(w.subjects||[]).map(x=>`<option value="${esc(x.name)}"></option>`).join('');$('draftCandidateCount').textContent=Number(c.draftCount||0).toLocaleString();$('approvedCandidateCount').textContent=Number(c.approvedCount||0).toLocaleString();$('draftCandidateBreakdown').textContent=`Preserved v0.5 candidate material: ${Number(c.questionCount||0).toLocaleString()} questions · ${Number(c.formulaCount||0).toLocaleString()} formulas · ${Number(c.definitionCount||0).toLocaleString()} definitions · ${Number(c.lessonIdeaCount||0).toLocaleString()} lesson ideas · ${Number(c.compareCount||0).toLocaleString()} needing comparison. New v0.6 outputs will be composed from staged source material instead.`;$('knowledgeMapSummary').innerHTML=[['Knowledge areas',(k.areas||[]).length],['Courses / collections',(k.courses||[]).length],['Subjects',(k.subjects||[]).length],['Topics',k.topicCount],['Multi-linked resources',k.multiLinkedResourceCount]].map(([l,v])=>`<div class="knowledge-stat"><span>${esc(l)}</span><strong>${Number(v||0).toLocaleString()}</strong></div>`).join('');$('workspaceSubjects').innerHTML=w.subjects?.length?w.subjects.map(x=>`<button class="workspace-card workspace-subject" data-name="${esc(x.name)}"><span class="eyebrow">${esc(w.courseLevel)}</span><strong>${esc(x.name)}</strong><span>${Number(x.resourceCount).toLocaleString()} organised resources · ${Number(x.moduleCount).toLocaleString()} preserved prototype modules</span></button>`).join(''):'<div class="empty">No subjects yet.</div>';$('workspaceLibraries').innerHTML=w.libraries?.map(x=>`<button class="workspace-card workspace-library" data-key="${esc(x.key)}"><span class="eyebrow">Resource view</span><strong>${esc(x.label)}</strong><span>${Number(x.resourceCount).toLocaleString()} resources</span><small>${esc(x.description)}</small></button>`).join('')||'';document.querySelectorAll('.workspace-subject').forEach(b=>b.addEventListener('click',()=>{$('searchBox').value=b.dataset.name||'';showView('library');}));document.querySelectorAll('.workspace-library').forEach(b=>b.addEventListener('click',()=>openWorkspaceLibrary(b.dataset.key)));}catch(e){toast(e.message,true);}}
  function openWorkspaceLibrary(key){activeWorkspaceLibraryKey=key||'';$('searchBox').value='';$('statusFilter').value='';$('kindFilter').value='';showView('library');}

  function closeBulkModal(){$('bulkModal').classList.remove('open');$('bulkModal').setAttribute('aria-hidden','true');activeBulkPreparation=null;activeBulkPurpose=null;}
  document.querySelectorAll('[data-close-bulk]').forEach(x=>x.addEventListener('click',closeBulkModal));
  async function prepareBulkAction(purpose,explicitIds=null){const ids=explicitIds?.length?explicitIds:selectedResourceIds();if(!ids.length)return;activeBulkPurpose=purpose;$('bulkModalTitle').textContent=purpose==='Organise'?'Organise selected resources':purpose==='CreateStudy'?'Create Study from selected resources':'Extract Learning from selected resources';$('bulkModalSubtitle').textContent='Analysing only your selected files. Existing saved analysis is reused when the source has not changed.';$('bulkPreparationList').innerHTML='<div class="empty">Analysing selected resources…</div>';$('bulkPrimaryAction').disabled=true;$('bulkModal').classList.add('open');$('bulkModal').setAttribute('aria-hidden','false');try{const r=await callHost('prepareBulkResources',{resourceIds:ids,purpose});activeBulkPreparation=r;$('bulkPreparationSummary').innerHTML=[['Selected',r.requested],['Analysed now',r.analysed],['Cached',r.reusedAnalysis],['Limited',r.limited],['Failed',r.failed]].map(([a,b])=>`<div><span>${esc(a)}</span><strong>${Number(b||0).toLocaleString()}</strong></div>`).join('');$('bulkPreparationList').innerHTML=r.items.length?r.items.map(x=>`<article class="bulk-prep-card"><div><strong>${esc(x.fileName)}</strong><div class="resource-meta"><span class="tag">${esc(x.scanStatus)}</span><span class="tag">${esc(x.suggestedResourceType)}</span>${x.suggestedLearningSubject?`<span class="tag organisation-learning">${esc(x.suggestedLearningSubject)}</span>`:''}${x.suggestedTopic?`<span class="tag organisation-topic">${esc(x.suggestedTopic)}</span>`:''}${x.relatedCopyCount?`<span class="tag">${x.relatedCopyCount+1} copies</span>`:''}</div><p class="muted">${esc(x.recommendation)}</p>${x.existingModuleId?`<div class="possible-duplicate">Existing learning: <strong>${esc(x.existingModuleTitle)}</strong> · ${Math.round(Number(x.existingSimilarity||0)*100)}% similarity</div>`:''}</div><span class="tag">${esc(x.suggestedStudyStatus)}</span></article>`).join(''):'<div class="empty">No usable selected resources.</div>';$('bulkPrimaryAction').textContent=purpose==='Organise'?'Apply organisation':purpose==='CreateStudy'?'Create / enrich Draft studies':'Extract Draft learning';$('bulkPrimaryAction').disabled=false;}catch(e){toast(e.message,true);closeBulkModal();}}
  async function runBulkPrimary(){if(!activeBulkPreparation||!activeBulkPurpose)return;const ids=activeBulkPreparation.items.map(x=>Number(x.resourceId));const b=$('bulkPrimaryAction');const old=b.textContent;b.disabled=true;b.textContent='Working…';try{if(activeBulkPurpose==='Organise'){const r=await callHost('applyBulkOrganisation',{resourceIds:ids});toast(`Organised ${r.updated} selected resources.`);}else if(activeBulkPurpose==='CreateStudy'){const r=await callHost('createBulkStudy',{resourceIds:ids});toast(`Create Study: ${r.created} Draft created, ${r.reusedExact} existing linked, ${r.skippedPossibleDuplicate} possible duplicates left for comparison, ${r.skippedIneligible||0} reference/ineligible skipped.${(r.created===0&&(r.skippedIneligible||0)>0)?' Use Extract Learning for the skipped reference material.':''}`);}else{const r=await callHost('extractBulkLearning',{resourceIds:ids});toast(`Extracted ${r.newCandidates} new Draft learning candidates; ${r.existingCandidatesLinked} exact matches gained another source; ${r.possibleDuplicatesForComparison} substantially similar candidates were queued for comparison.`);}closeBulkModal();await loadResources();await loadLearningModules();await loadWorkspace();}catch(e){toast(e.message,true);}finally{b.disabled=false;b.textContent=old;}}

  function candidateTypeLabel(type){return ({LessonIdea:'Lesson idea'})[type]||type;}
  function selectedCandidateIds(){return [...document.querySelectorAll('.candidate-check-input:checked')].map(x=>Number(x.dataset.id)).filter(Boolean);}
  function updateCandidateSelection(){const ids=selectedCandidateIds();$('selectedCandidateCount').textContent=`${ids.length} selected`;['approveCandidates','draftCandidates','rejectCandidates'].forEach(id=>$(id).disabled=!ids.length);$('selectAllCandidates').checked=!!activeCandidateItems.length&&ids.length===activeCandidateItems.length;}
  function renderCandidateStats(s){const other=Number(s.practicalCount||0)+Number(s.safetyCount||0)+Number(s.otherCount||0);$('buildApprovedCandidates').disabled=Number(s.approvedCount||0)===0;const stats=[['Draft',s.draftCount],['Needs comparison',s.compareCount],['Questions',s.questionCount],['Formulas',s.formulaCount],['Definitions',s.definitionCount],['Lesson ideas',s.lessonIdeaCount],['Other Draft',other],['Approved',s.approvedCount],['Used in study',s.usedCount],['Rejected',s.rejectedCount],['Question Bank',s.questionBankCount],['Formula Library',s.formulaLibraryCount]];$('candidateStats').innerHTML=stats.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${Number(value||0).toLocaleString()}</strong></div>`).join('');}
  function renderCandidateCard(x){const context=[x.learningSubject,x.topic,x.subtopic].filter(Boolean).map(v=>`<span class="tag">${esc(v)}</span>`).join('');const type=String(x.candidateType||'');const duplicateHint=x.possibleDuplicateOfId?`<div class="possible-duplicate">Possible existing candidate: <strong>${esc(x.possibleDuplicateTitle||('Candidate #'+x.possibleDuplicateOfId))}</strong> · ${Math.round(Number(x.possibleDuplicateSimilarity||0)*100)}% similar. Review before deciding whether both are useful.</div>`:'';const canPromote=x.status!=='Compare'&&x.status!=='Rejected';const extra=!canPromote?'':type==='Question'?`<button class="secondary-btn candidate-question-bank" data-id="${x.id}">Question Bank</button>`:type==='Formula'?`<button class="secondary-btn candidate-formula-bank" data-id="${x.id}">Formula Library</button>`:type==='LessonIdea'?`<button class="secondary-btn candidate-create-lesson" data-id="${x.id}">Create Draft Lesson</button>`:'';return `<article class="learning-candidate-card"><label class="candidate-check"><input class="candidate-check-input" type="checkbox" data-id="${x.id}"></label><div class="candidate-main"><div class="candidate-head"><div><div class="candidate-tags"><span class="pill">${esc(candidateTypeLabel(type))}</span><span class="tag status-${esc(x.status)}">${esc(x.status)}</span><span class="tag">${Number(x.sourceCount||0)} source${Number(x.sourceCount||0)===1?'':'s'}</span>${x.targetModuleId?`<span class="tag candidate-bank-tag">Lesson #${x.targetModuleId}</span>`:''}</div><h3>${esc(x.title||candidateTypeLabel(type))}</h3></div><span class="candidate-confidence">${Math.round(Number(x.confidence||0)*100)}% extraction confidence</span></div><div class="candidate-body">${esc(x.body||x.title||'')}</div><div class="candidate-context">${context||'<span class="muted">No topic assigned yet</span>'}</div>${duplicateHint}<div class="candidate-actions"><button class="secondary-btn candidate-sources" data-id="${x.id}">View sources</button>${x.possibleDuplicateOfId?`<button class="secondary-btn candidate-match" data-id="${x.id}" data-match="${x.possibleDuplicateOfId}">View possible match</button>`:''}<button class="secondary-btn candidate-edit" data-id="${x.id}">Edit</button>${x.status!=='Approved'&&x.status!=='Used'?`<button class="secondary-btn candidate-approve" data-id="${x.id}">Approve</button>`:''}${x.status!=='Rejected'?`<button class="danger-btn candidate-reject" data-id="${x.id}">Reject</button>`:''}${extra}${canPromote?`<button class="primary-btn candidate-add-module" data-id="${x.id}">Add to target lesson</button>`:''}</div><div id="candidateSources-${x.id}" class="candidate-source-panel" hidden></div><div id="candidateCompare-${x.id}" class="candidate-source-panel" hidden></div></div></article>`;}
  function bindCandidateActions(){document.querySelectorAll('.candidate-check-input').forEach(x=>x.addEventListener('change',updateCandidateSelection));document.querySelectorAll('.candidate-sources').forEach(b=>b.addEventListener('click',()=>toggleCandidateSources(Number(b.dataset.id))));document.querySelectorAll('.candidate-match').forEach(b=>b.addEventListener('click',()=>toggleCandidateMatch(Number(b.dataset.id),Number(b.dataset.match))));document.querySelectorAll('.candidate-edit').forEach(b=>b.addEventListener('click',()=>openCandidateEdit(Number(b.dataset.id))));document.querySelectorAll('.candidate-approve').forEach(b=>b.addEventListener('click',()=>setCandidateStatus([Number(b.dataset.id)],'Approved')));document.querySelectorAll('.candidate-reject').forEach(b=>b.addEventListener('click',()=>setCandidateStatus([Number(b.dataset.id)],'Rejected')));document.querySelectorAll('.candidate-question-bank').forEach(b=>b.addEventListener('click',()=>candidateToBank(Number(b.dataset.id),'Question')));document.querySelectorAll('.candidate-formula-bank').forEach(b=>b.addEventListener('click',()=>candidateToBank(Number(b.dataset.id),'Formula')));document.querySelectorAll('.candidate-create-lesson').forEach(b=>b.addEventListener('click',()=>createLessonFromCandidate(Number(b.dataset.id))));document.querySelectorAll('.candidate-add-module').forEach(b=>b.addEventListener('click',()=>addCandidateToTargetLesson(Number(b.dataset.id))));updateCandidateSelection();}
  async function loadCandidates(){try{const status=$('candidateStatus').value,type=$('candidateType').value,learningSubject=$('candidateLearningSubject').value,search=$('candidateSearch').value.trim();const [summary,items,w,modules]=await Promise.all([callHost('getCandidateReviewSummary',{courseLevel:'ONC'}),callHost('getLearningCandidates',{courseLevel:'ONC',status,candidateType:type,learningSubject,search,limit:250}),callHost('getWorkspaceOverview',{courseLevel:'ONC'}),callHost('getLearningModules')]);activeCandidateItems=items||[];renderCandidateStats(summary);const currentSubject=$('candidateLearningSubject').value;$('candidateLearningSubject').innerHTML='<option value="">All ONC subjects</option>'+(w.subjects||[]).map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('');$('candidateLearningSubject').value=currentSubject;const currentModule=$('candidateTargetModule').value;$('candidateTargetModule').innerHTML='<option value="">Choose an existing Study Builder lesson…</option>'+(modules||[]).map(m=>`<option value="${m.id}">${esc([m.learningSubject,m.topic,m.title].filter(Boolean).join(' › '))}</option>`).join('');if([...$('candidateTargetModule').options].some(o=>o.value===currentModule))$('candidateTargetModule').value=currentModule;$('candidateSummary').textContent=`Showing ${activeCandidateItems.length}${activeCandidateItems.length>=250?' (maximum 250 per view)':''} candidate${activeCandidateItems.length===1?'':'s'}. Original source files are never modified.`;$('candidateList').innerHTML=activeCandidateItems.length?activeCandidateItems.map(renderCandidateCard).join(''):'<div class="empty">No learning candidates match these filters.</div>';bindCandidateActions();}catch(e){toast(e.message,true);}}
  async function toggleCandidateSources(id){const panel=$(`candidateSources-${id}`);if(!panel)return;if(!panel.hidden){panel.hidden=true;return;}panel.hidden=false;panel.innerHTML='<div class="muted">Loading sources…</div>';try{const d=await callHost('getLearningCandidate',{candidateId:id});panel.innerHTML=(d.sources||[]).length?(d.sources||[]).map(src=>`<div class="candidate-source-row"><div><strong>${esc(src.fileName)}</strong><div class="path">${esc(src.sourceName)} / ${esc(src.relativePath)}</div>${src.locationNote?`<div class="muted">${esc(src.locationNote)}</div>`:''}</div><button class="secondary-btn open-candidate-source" data-resource="${src.resourceId}">Open source</button></div>`).join(''):'<div class="muted">No source relationship is stored for this candidate.</div>';document.querySelectorAll(`#candidateSources-${id} .open-candidate-source`).forEach(b=>b.addEventListener('click',async()=>{try{await callHost('openResource',{resourceId:Number(b.dataset.resource)});}catch(e){toast(e.message,true);}}));}catch(e){panel.innerHTML=`<div class="muted">${esc(e.message)}</div>`;}}
  async function toggleCandidateMatch(id,matchId){const panel=$(`candidateCompare-${id}`);if(!panel)return;if(!panel.hidden){panel.hidden=true;return;}panel.hidden=false;panel.innerHTML='<div class="muted">Loading possible match…</div>';try{const d=await callHost('getLearningCandidate',{candidateId:matchId});const c=d.candidate;panel.innerHTML=`<div class="analysis-note"><strong>${esc(c.title||candidateTypeLabel(c.candidateType))}</strong><p>${esc(c.body||c.title||'')}</p><p class="muted">${esc([c.learningSubject,c.topic,c.subtopic].filter(Boolean).join(' › '))} · ${Number(c.sourceCount||0)} source${Number(c.sourceCount||0)===1?'':'s'} · ${esc(c.status)}</p></div>`;}catch(e){panel.innerHTML=`<div class="muted">${esc(e.message)}</div>`;}}
  async function setCandidateStatus(ids,status){if(!ids.length)return;try{const r=await callHost('setLearningCandidateStatus',{candidateIds:ids,status});toast(`${r.updated} learning candidate${r.updated===1?'':'s'} set to ${status}.`);await loadCandidates();await loadWorkspace();}catch(e){toast(e.message,true);}}
  async function openCandidateEdit(id){try{const d=await callHost('getLearningCandidate',{candidateId:id});activeCandidateEditId=id;$('candidateEditTitleInput').value=d.candidate.title||'';$('candidateEditBody').value=d.candidate.body||'';$('candidateEditSubject').value=d.candidate.learningSubject||'';$('candidateEditTopic').value=d.candidate.topic||'';$('candidateEditSubtopic').value=d.candidate.subtopic||'';$('candidateEditTitle').textContent=`Edit ${candidateTypeLabel(d.candidate.candidateType)}`;$('candidateEditModal').classList.add('open');$('candidateEditModal').setAttribute('aria-hidden','false');}catch(e){toast(e.message,true);}}
