  async function saveCandidateEdit(){if(!activeCandidateEditId)return;try{await callHost('updateLearningCandidate',{candidateId:activeCandidateEditId,title:$('candidateEditTitleInput').value.trim(),body:$('candidateEditBody').value.trim(),learningSubject:$('candidateEditSubject').value.trim(),topic:$('candidateEditTopic').value.trim(),subtopic:$('candidateEditSubtopic').value.trim()});closeCandidateEdit();toast('Learning candidate saved.');await loadCandidates();}catch(e){toast(e.message,true);}}
  async function candidateToBank(id,type){try{const r=await callHost(type==='Question'?'addCandidateToQuestionBank':'addCandidateToFormulaLibrary',{candidateId:id});toast(r.message);await loadCandidates();await loadWorkspace();}catch(e){toast(e.message,true);}}
  async function addCandidateToTargetLesson(id){const moduleId=Number($('candidateTargetModule').value||0);if(!moduleId){toast('Choose a target lesson at the top of Learning Review first.',true);return;}try{const r=await callHost('addCandidateToModule',{candidateId:id,moduleId});toast(r.message);await loadCandidates();await loadWorkspace();await loadLearningModules();}catch(e){toast(e.message,true);}}
