  function closeApprovedStudy(){ $('approvedStudyModal').classList.remove('open');$('approvedStudyModal').setAttribute('aria-hidden','true');activeApprovedStudyProposal=null;}
  function selectedApprovedGroupKeys(){return [...document.querySelectorAll('.approved-group-check:checked')].map(x=>x.dataset.key).filter(Boolean);}
  function updateApprovedGroupSelection(){const keys=selectedApprovedGroupKeys();$('selectedApprovedGroupCount').textContent=`${keys.length} selected`;$('buildApprovedStudyNow').disabled=!keys.length;const buildable=[...document.querySelectorAll('.approved-group-check:not(:disabled)')];$('selectAllApprovedGroups').checked=!!buildable.length&&keys.length===buildable.length;}
  function renderApprovedStudyGroup(g){const counts=[g.questionCount?`${g.questionCount} questions`:'',g.formulaCount?`${g.formulaCount} formulas`:'',g.definitionCount?`${g.definitionCount} definitions`:'',g.lessonIdeaCount?`${g.lessonIdeaCount} lesson ideas`:'',g.practicalCount?`${g.practicalCount} practical`:'',g.safetyCount?`${g.safetyCount} safety`:'',g.otherCount?`${g.otherCount} other`:'' ].filter(Boolean).join(' · ');const blocked=!g.isBuildable||g.needsLessonComparison;const match=g.existingModuleId?`<div class="possible-duplicate ${g.exactExisting?'approved-existing':''}">${g.exactExisting?'Existing lesson will be enriched':'Possible existing lesson'}: <strong>${esc(g.existingModuleTitle||'Study Builder lesson')}</strong> · ${Math.round(Number(g.existingSimilarity||0)*100)}% similarity</div>`:'';return `<article class="approved-study-group ${blocked?'approved-group-blocked':''}"><label class="approved-study-check"><input class="approved-group-check" type="checkbox" data-key="${esc(g.groupKey)}" ${blocked?'disabled':''}></label><div><p class="eyebrow">${esc([g.courseLevel,g.learningSubject].filter(Boolean).join(' · '))}</p><h3>${esc(g.proposedTitle)}</h3><div class="candidate-context">${g.topic?`<span class="tag">${esc(g.topic)}</span>`:''}${g.subtopic?`<span class="tag">${esc(g.subtopic)}</span>`:''}<span class="tag">${Number(g.candidateCount||0)} approved</span><span class="tag">${Number(g.sourceCount||0)} sources</span></div>${counts?`<p class="muted approved-study-counts">${esc(counts)}</p>`:''}${match}<p class="muted">${esc(g.recommendation)}</p></div></article>`;}
  async function openApprovedStudyBuilder(){const modal=$('approvedStudyModal');$('approvedStudyGroups').innerHTML='<div class="empty">Checking approved candidates and existing Study Builder lessons…</div>';$('approvedStudySummary').innerHTML='';$('buildApprovedStudyNow').disabled=true;modal.classList.add('open');modal.setAttribute('aria-hidden','false');try{const p=await callHost('getApprovedStudyProposal',{courseLevel:'ONC'});activeApprovedStudyProposal=p;$('approvedStudySummary').innerHTML=[['Approved',p.approvedCandidateCount],['Buildable candidates',p.buildableCandidateCount],['Proposed groups',p.groupCount],['Buildable groups',p.buildableGroupCount],['Needs comparison',p.comparisonGroupCount]].map(([a,b])=>`<div><span>${esc(a)}</span><strong>${Number(b||0).toLocaleString()}</strong></div>`).join('');$('approvedStudyGroups').innerHTML=(p.groups||[]).length?(p.groups||[]).map(renderApprovedStudyGroup).join(''):'<div class="empty">No Approved learning candidates are waiting to be built. Approve useful candidates in Learning Review first.</div>';document.querySelectorAll('.approved-group-check').forEach(x=>x.addEventListener('change',updateApprovedGroupSelection));$('selectAllApprovedGroups').checked=false;updateApprovedGroupSelection();}catch(e){toast(e.message,true);closeApprovedStudy();}}
  async function buildApprovedStudy(){const keys=selectedApprovedGroupKeys();if(!keys.length)return;const b=$('buildApprovedStudyNow'),old=b.textContent;b.disabled=true;b.textContent='Building Draft lessons…';try{const r=await callHost('buildApprovedStudy',{courseLevel:'ONC',groupKeys:keys});const used=[r.questionsUsed?`${r.questionsUsed} questions`:'',r.formulasUsed?`${r.formulasUsed} formulas`:'',r.definitionsUsed?`${r.definitionsUsed} definitions`:'',r.lessonIdeasUsed?`${r.lessonIdeasUsed} lesson ideas`:'',r.practicalUsed?`${r.practicalUsed} practical`:'',r.safetyUsed?`${r.safetyUsed} safety`:'',r.otherUsed?`${r.otherUsed} other`:''].filter(Boolean).join(', ');const message=`Approved → Study Builder: ${r.modulesCreated} new Draft lesson${r.modulesCreated===1?'':'s'}, ${r.existingModulesEnriched} existing enriched, ${r.candidatesUsed} candidates used${used?` (${used})`:''}, ${r.questionsAddedToBank} questions banked, ${r.formulasAddedToLibrary} formulas stored${r.candidatesSkippedForSimilarity?`, ${r.candidatesSkippedForSimilarity} block similarities queued for comparison`:''}${r.groupsSkippedForComparison?`, ${r.groupsSkippedForComparison} lesson groups left for comparison`:''}.`;closeApprovedStudy();toast(message);await loadCandidates();await loadWorkspace();showView('learning');await loadLearningModules();const first=(r.moduleIds||[])[0];if(first)await openLearningModule(Number(first));}catch(e){toast(e.message,true);b.disabled=false;b.textContent=old;}}

  async function loadUpdateStatus(){try{const r=await callHost('getUpdateStatus');$('updateVersion').textContent=`Version ${r.currentVersion}`;$('updateMessage').textContent=r.message;$('updateInstallState').textContent=r.isInstalledBuild?'Installed build':'Source / development build';}catch(e){toast(e.message,true);}}
  async function checkUpdates(){try{const r=await callHost('checkForUpdates');$('updateMessage').textContent=r.message;toast(r.message);}catch(e){toast(e.message,true);}}
  async function chooseUpdatePackage(){try{const r=await callHost('pickUpdatePackage');if(r.cancelled)return;const panel=$('stagedUpdate');panel.hidden=false;panel.innerHTML=`<strong>Update v${esc(r.targetVersion)} staged</strong><p>${esc(r.message)}</p><div class="path">Backup: ${esc(r.backupDirectory||'')}</div>${r.canApply?'<button id="applyStagedUpdate" class="primary-btn">Apply & restart</button>':''}`;stagedUpdateScript=r.applyScript||null;$('applyStagedUpdate')?.addEventListener('click',applyStagedUpdate);}catch(e){toast(e.message,true);}}
  async function applyStagedUpdate(){if(!stagedUpdateScript)return;if(!confirm('Apply the staged update and restart WICareerBuilder? The installed application and database have already been backed up.'))return;try{const r=await callHost('applyStagedUpdate',{scriptPath:stagedUpdateScript});toast(r.message);}catch(e){toast(e.message,true);}}

